// Life Orientation lessons — loaded on demand by ensureLessons('lifeori') in index.html.
// Shape: LESSON_DB.lifeori.m<moduleIndex>[topicIndex] = lesson. Order matches COURSE_DATA.lifeori.
// Two lessons (m0[0], m2[0]) are hand-written inside index.html; _loAdd merges the missing parts.
// Helplines and thresholds change — check current numbers before relying on them.
LESSON_DB.lifeori = LESSON_DB.lifeori || {};
function _loAdd(m, lessons){ LESSON_DB.lifeori[m] = LESSON_DB.lifeori[m] || {}; Object.keys(lessons).forEach(function(i){ LESSON_DB.lifeori[m][i] = Object.assign(LESSON_DB.lifeori[m][i] || {}, lessons[i]); }); }

// ─── Module 0: Development of the Self ──────────────────────────────────────
_loAdd('m0', {
  0: {subtitle:"Grade 10 · Understanding who you are and how you grow",
    hook:{title:"The filtered feed", body:"Scroll through Instagram or TikTok and everyone seems to have perfect skin, a perfect body and a perfect life. Then you look in the mirror. Research shows that comparing yourself to edited images lowers self-esteem — even when you <em>know</em> they're filtered. Self-esteem is how you value yourself, and the good news is that it can be built."},
    examples:[
      {title:"Healthy or unhealthy self-talk?", body:"“I failed this test, so I'm stupid.”", answer:"<strong>Unhealthy</strong>. Healthier: “I failed this test, so I need to change how I study.” It's about the action, not your worth."},
      {title:"Where does it come from?", body:"Name two influences on a teenager's self-esteem.", answer:"<strong>Family</strong> (how you're spoken to) and <strong>peers and social media</strong> (acceptance, comparison)."},
      {title:"Building confidence", body:"Give one practical way to build self-esteem.", answer:"<strong>Set a small, achievable goal and reach it</strong> — e.g. running 2 km three times this week. Each success is evidence you can do things."},
    ],
    mistakes:["Thinking self-esteem means believing you're better than others.","Comparing your “behind the scenes” to everyone else's highlight reel.","Waiting to feel confident before trying — confidence usually comes after action."],
    activityAnswer:"Answers are personal. A good list includes character strengths (kind, honest), skills (good at drawing) and achievements. The point is noticing strengths others see in you that you overlooked.",
    quiz:[
      {q:"Self-esteem is:",opts:["How others see you","How you value yourself","How popular you are","Your exam marks"],a:1,et:"It's your own sense of your worth."},
      {q:"Which is healthy self-talk after a mistake?",opts:["I'm useless","I always fail","I can learn from this","Nobody likes me"],a:2,et:"Focus on the action, not your worth."},
      {q:"Comparing yourself to filtered social media images usually:",opts:["Raises self-esteem","Lowers self-esteem","Has no effect","Improves marks"],a:1,et:"You compare your real life to someone's edited highlights."},
    ],
    conclusion:"Self-esteem isn't fixed. Notice your strengths, talk to yourself kindly, and build evidence through small wins."},

  1: {emoji:"💞", subtitle:"Grade 10 · Respect, trust and red flags",
    illusText:"“If you loved me, you'd give me your password” — that's not love, it's control.",
    hook:{title:"The password test", body:"Lerato's boyfriend says: “If you really loved me, you'd give me your phone password.” Then he starts checking who she talks to and getting angry when she spends time with friends. It can look like caring — but it's <strong>control</strong>. Learning the difference between healthy and unhealthy relationships protects you in friendships, families and dating."},
    intro:"<strong>Healthy relationships</strong> are built on <strong>respect</strong>, <strong>trust</strong>, <strong>honest communication</strong>, <strong>equality</strong> and <strong>boundaries</strong> — both people can say no and still feel safe. <strong>Unhealthy relationships</strong> include control, jealousy, pressure, put-downs, isolation from friends and family, and threats. <strong>Abusive</strong> relationships involve physical, emotional, sexual, financial or digital abuse (e.g. tracking your phone, sharing private images). <strong>Consent</strong> must be freely given, informed and can be withdrawn at any time.",
    concepts:[
      {t:"green", title:"✅ Green flags", body:"Respects your “no”, supports your goals, is happy you have friends, talks problems through calmly, is the same in private and public."},
      {t:"teal", title:"🚩 Red flags", body:"Checks your phone, decides what you wear, isolates you from friends, extreme jealousy, threats, guilt-tripping (“after everything I do for you…”)."},
      {t:"gold", title:"🛑 Consent", body:"Yes must be free, sober, informed and ongoing. Silence or pressure is not consent. You can change your mind at any time."},
    ],
    examples:[
      {title:"Healthy or not?", body:"A partner gets angry every time you go out with friends without them.", answer:"<strong>Unhealthy</strong> — controlling and isolating."},
      {title:"Consent", body:"Someone agreed earlier but now says they want to stop.", answer:"<strong>Consent has been withdrawn</strong> — you must stop."},
      {title:"Digital abuse", body:"Give an example of digital abuse.", answer:"<strong>Sharing someone's private images without permission</strong>, tracking their location, or demanding passwords."},
    ],
    mistakes:["Mistaking jealousy for love.","Thinking abuse is only physical.","Believing you must stay because you've been together a long time."],
    callout:{title:"Get help", body:"Talk to someone you trust. Childline South Africa: 116 (free). GBV Command Centre: 0800 428 428. In danger: SAPS 10111."},
    activity:"Make two lists: five signs of a healthy relationship and five red flags. Rank the red flags from most to least serious.",
    activityAnswer:"Healthy: respect, trust, honesty, support, boundaries. Red flags (most serious first): threats or violence, sexual pressure, isolation, phone control, constant put-downs.",
    examTip:"In LO answers, use correct terms (boundaries, consent, coercion) and give a practical action, e.g. where to get help.",
    keyterms:[{w:"Boundary",d:"A limit you set for how others may treat you"},{w:"Consent",d:"Freely given, informed agreement that can be withdrawn"},{w:"Coercion",d:"Pressuring someone into something against their will"}],
    quiz:[
      {q:"Which is a red flag?",opts:["Supporting your goals","Checking your phone without permission","Respecting your no","Meeting your friends"],a:1,et:"Controlling behaviour is a warning sign."},
      {q:"Consent can be withdrawn:",opts:["Never","At any time","Only before starting","Only in writing"],a:1,et:"A yes can change to a no."},
      {q:"Childline South Africa's free number is:",opts:["10111","116","112","0800 123"],a:1,et:"Childline: 116."},
    ],
    conclusion:"Love doesn't control. Know the green flags, spot the red ones, and speak up early."},

  2: {emoji:"🗣️", subtitle:"Grade 10 · Saying no without losing yourself",
    illusText:"“Nah, I'm good” — two words that take courage.",
    hook:{title:"The house party", body:"At a friend's party, someone passes around a vape and a bottle. “Come on, everyone's doing it.” You don't want to — but you don't want to look boring either. Peer pressure isn't always loud; often it's a look, a laugh or silence. <strong>Assertiveness</strong> is the skill of saying what you mean, respectfully, without giving in or attacking."},
    intro:"There are three main communication styles. <strong>Passive</strong>: avoiding conflict, giving in, not saying what you need. <strong>Aggressive</strong>: forcing your view, insulting or threatening. <strong>Assertive</strong>: stating your feelings and needs clearly and respectfully, while respecting others. <strong>Peer pressure</strong> can be positive (friends encouraging you to study) or negative. Refusal skills include a clear “no”, an <strong>“I” statement</strong>, suggesting an alternative, and walking away.",
    concepts:[
      {t:"green", title:"💬 “I” statements", body:"“I feel ___ when ___ because ___. I'd like ___.” — e.g. “I feel uncomfortable when you push me to drink. I'd like you to respect my choice.”"},
      {t:"teal", title:"🛑 Refusal skills", body:"Say no clearly, repeat it (broken record), give a short reason or none, suggest something else, leave if needed."},
      {t:"gold", title:"👥 Choose your crowd", body:"Friends who respect your choices make saying no easier. Positive peer pressure is real too."},
    ],
    examples:[
      {title:"Name the style", body:"“Fine, whatever you want” (while feeling upset).", answer:"<strong>Passive</strong> — not expressing real needs."},
      {title:"Make it assertive", body:"“You're an idiot for asking me that!”", answer:"“<strong>No thanks — that's not for me.</strong>” Clear, calm, respectful."},
      {title:"Positive pressure", body:"Give an example of positive peer pressure.", answer:"Friends forming a <strong>study group</strong> and encouraging you to join."},
    ],
    mistakes:["Thinking assertive means aggressive.","Over-explaining a no — a short no is enough.","Believing you must stay in a situation to keep friends."],
    callout:{title:"Exit plan", body:"Agree on a code word with a parent or friend: if you text it, they call to “need” you home. It's an easy way out."},
    activity:"Write an assertive response to: “If you don't skip school with us, you're not our friend.”",
    activityAnswer:"Example: “I'm not skipping school — I need to pass this year. I'll see you guys after school.”",
    examTip:"When asked to explain assertiveness, compare it with passive and aggressive behaviour and give an example of each.",
    keyterms:[{w:"Assertive",d:"Expressing needs clearly and respectfully"},{w:"Peer pressure",d:"Influence from people of a similar age"},{w:"“I” statement",d:"A sentence that describes your feelings without blaming"}],
    quiz:[
      {q:"“No thanks, that's not for me” is:",opts:["Passive","Aggressive","Assertive","Rude"],a:2,et:"Clear and respectful."},
      {q:"Giving in to avoid conflict is:",opts:["Passive","Assertive","Aggressive","Healthy"],a:0,et:"Your needs aren't expressed."},
      {q:"Friends encouraging you to study is:",opts:["Negative peer pressure","Positive peer pressure","Bullying","Aggression"],a:1,et:"Pressure can be positive."},
    ],
    conclusion:"Assertiveness protects your choices and your friendships. A clear, calm no is a skill you can practise."},

  3: {emoji:"🧭", subtitle:"Grade 10–11 · Values, choices and your rights",
    illusText:"In South Africa, anyone aged 12 or older can get contraception at a clinic without a parent's consent.",
    hook:{title:"Decisions under pressure", body:"Big decisions about relationships and sex are often made in the moment — under pressure, after drinking, or because “everyone's doing it”. Informed decision-making means deciding <em>before</em> the moment: knowing your values, the facts, the risks and your rights, so the choice is really yours."},
    intro:"<strong>Sexuality</strong> includes your body, feelings, identity, relationships and values. Making <strong>informed decisions</strong> uses a process: identify the decision, list options, consider consequences (health, emotional, legal, future goals), check against your values, decide and review. Choosing to <strong>delay sexual activity</strong> is a valid choice. If sexually active, <strong>condoms</strong> protect against both pregnancy and STIs including HIV; other <strong>contraceptives</strong> (pill, injection, implant) prevent pregnancy only. Under the <strong>Children's Act</strong>, young people aged 12 and older can get contraceptives and confidential advice at clinics without parental consent.",
    concepts:[
      {t:"green", title:"🧠 Decision process", body:"Stop → think about options → consequences → values → decide → review."},
      {t:"teal", title:"🛡️ Protection", body:"Condoms (male or female) are the only method that protects against both pregnancy and STIs."},
      {t:"gold", title:"🏥 Your rights", body:"Confidential, youth-friendly services at clinics; the right to say no; the right to accurate information."},
    ],
    examples:[
      {title:"Which method protects against HIV?", body:"Pill, injection or condom?", answer:"Only the <strong>condom</strong> protects against HIV and other STIs."},
      {title:"Apply the process", body:"Your partner pressures you. What's the first step?", answer:"<strong>Pause and identify the decision</strong> — you don't have to decide in the moment."},
      {title:"Rights", body:"Can a 15-year-old get contraception at a clinic without a parent?", answer:"<strong>Yes</strong> — from age 12, confidentially."},
    ],
    mistakes:["Thinking the pill protects against STIs.","Believing “everyone is doing it” — many teenagers choose to wait.","Making decisions under the influence of alcohol or drugs."],
    callout:{title:"Talk to someone", body:"Clinics, school nurses, loveLife and trusted adults can give accurate information. Avoid relying on rumours from social media."},
    activity:"Use the decision-making steps for this scenario: you're invited to a party where you know there will be alcohol and older guys. Write each step.",
    activityAnswer:"Decision: go or not? Options: go with a trusted friend and leave by 10 p.m.; don't go; go with a plan. Consequences: safety risks, pressure. Values: safety, family trust. Decision: e.g. go with a friend, no drinking, transport arranged. Review afterwards.",
    examTip:"Use the steps of decision-making by name, and link each consequence to health, emotional, social or legal effects.",
    keyterms:[{w:"Informed decision",d:"A choice made using accurate information and your values"},{w:"Contraception",d:"Methods used to prevent pregnancy"},{w:"STI",d:"Sexually transmitted infection"}],
    quiz:[
      {q:"Which method protects against both pregnancy and STIs?",opts:["The pill","The injection","Condoms","The implant"],a:2,et:"Condoms are the only dual-protection method."},
      {q:"In SA, clinics can provide contraceptives without parental consent from age:",opts:["10","12","16","18"],a:1,et:"Under the Children's Act."},
      {q:"The first step of decision-making is to:",opts:["Act quickly","Identify the decision","Ask friends to decide","Ignore it"],a:1,et:"Then list options and consequences."},
    ],
    conclusion:"Your body, your choices — made with facts, values and rights, not pressure."},

  4: {emoji:"🎗️", subtitle:"Grade 10–12 · Facts, prevention and living positively",
    illusText:"Undetectable = untransmittable: someone on effective treatment does not pass HIV on sexually.",
    hook:{title:"The country with the most people living with HIV", body:"South Africa has the largest number of people living with HIV in the world — around 7.7 million. But it also runs the world's biggest HIV treatment programme. Today, a person who tests early and takes treatment can live a long, healthy life. The biggest enemies are no longer the virus alone, but <strong>stigma</strong> and <strong>not knowing your status</strong>."},
    intro:"<strong>HIV</strong> (human immunodeficiency virus) attacks the immune system; without treatment it can lead to <strong>AIDS</strong>. HIV is passed through <strong>blood, semen, vaginal fluids and breast milk</strong> — not through hugging, sharing cups, toilets or mosquitoes. Prevention: <strong>condoms</strong>, <strong>PrEP</strong> (a daily pill for HIV-negative people at risk), <strong>voluntary medical male circumcision</strong> (reduces risk), and <strong>PEP</strong> (emergency treatment started within 72 hours after possible exposure). <strong>Antiretroviral treatment (ARVs)</strong> keeps the virus under control. When the viral load is <strong>undetectable</strong>, HIV is not passed on sexually — <strong>U = U</strong>.",
    concepts:[
      {t:"green", title:"🧪 Know your status", body:"HIV tests are free and confidential at clinics. Results in about 20 minutes with rapid tests."},
      {t:"teal", title:"💊 Treatment works", body:"ARVs taken daily reduce the virus to undetectable levels, protecting the person's health and their partners."},
      {t:"gold", title:"🤝 Fight stigma", body:"Stigma stops people testing and taking treatment. Treat people living with HIV with dignity — it's also their constitutional right."},
    ],
    examples:[
      {title:"Myth or fact?", body:"You can get HIV from sharing a cup.", answer:"<strong>Myth</strong> — HIV isn't spread through saliva, cups or touch."},
      {title:"PEP", body:"Within how long must PEP be started?", answer:"Within <strong>72 hours</strong> of possible exposure — the sooner the better."},
      {title:"U = U", body:"What does U = U mean?", answer:"<strong>Undetectable = untransmittable</strong> — with an undetectable viral load, HIV is not transmitted sexually."},
    ],
    mistakes:["Believing myths about how HIV spreads.","Thinking HIV is a death sentence — with treatment, life expectancy is near normal.","Confusing PrEP (before exposure) with PEP (after exposure)."],
    callout:{title:"Where to go", body:"Any public clinic offers free testing, condoms, PrEP and ARVs. The AIDS Helpline: 0800 012 322."},
    activity:"Design a poster that busts three common HIV myths with facts.",
    activityAnswer:"Example myths: “You can get HIV from mosquitoes” (no); “You can tell by looking” (no — only a test tells); “HIV means death” (no — treatment works). Each with a short fact.",
    examTip:"Separate prevention, testing and treatment in your answer, and include social aspects (stigma, rights).",
    keyterms:[{w:"ARVs",d:"Antiretroviral medicines that control HIV"},{w:"PrEP",d:"Pre-exposure prophylaxis — a daily pill to prevent HIV"},{w:"Stigma",d:"Negative beliefs and discrimination against a group"}],
    quiz:[
      {q:"HIV can be transmitted through:",opts:["Hugging","Sharing cups","Blood","Mosquito bites"],a:2,et:"Also semen, vaginal fluids and breast milk."},
      {q:"PEP must be started within:",opts:["72 hours","7 days","1 month","1 year"],a:0,et:"After possible exposure."},
      {q:"U = U means:",opts:["Untested = unsafe","Undetectable = untransmittable","Unknown = unprotected","Unwell = untreatable"],a:1,et:"Effective treatment prevents sexual transmission."},
    ],
    conclusion:"Test, protect, treat and respect. Facts — not fear — beat HIV."},

  5: {emoji:"🟣", subtitle:"Grade 10–12 · Recognising abuse and getting help",
    illusText:"#AmINext — the question South African women asked in 2019.",
    hook:{title:"#AmINext", body:"In 2019, the murder of UCT student Uyinene Mrwetyana sparked national protests under the hashtag <strong>#AmINext</strong>. Thousands marched to Parliament demanding action on <strong>gender-based violence (GBV)</strong>. GBV affects people of every background — and ending it needs everyone, including young men, to speak up and step in."},
    intro:"<strong>Gender-based violence</strong> is violence directed at someone because of their gender. It includes <strong>physical</strong>, <strong>sexual</strong>, <strong>emotional/psychological</strong>, <strong>economic</strong> (controlling money) and <strong>digital</strong> abuse. Causes include harmful gender norms, power imbalances, alcohol and drug abuse, and cycles of violence. The <strong>Domestic Violence Act (1998)</strong> lets victims apply for a <strong>protection order</strong> at a magistrate's court. Support: the GBV Command Centre (0800 428 428), SAPS (10111), Childline (116) and Thuthuzela Care Centres for rape survivors.",
    concepts:[
      {t:"green", title:"🔍 Recognise it", body:"Hitting, forced sex, threats, humiliation, controlling money or movement, stalking, sharing private images."},
      {t:"teal", title:"🛡️ Protection order", body:"Apply at a magistrate's court — free. It orders the abuser to stop and can bar them from your home."},
      {t:"gold", title:"🙋 Bystander action", body:"Distract, delegate (get help), document, delay (check in afterwards) or directly intervene — if it's safe."},
    ],
    examples:[
      {title:"Type of abuse", body:"A partner takes their girlfriend's SASSA grant and decides how it's spent.", answer:"<strong>Economic abuse</strong>."},
      {title:"Legal help", body:"Where can someone apply for a protection order?", answer:"At a <strong>magistrate's court</strong>, free of charge."},
      {title:"Be an upstander", body:"Your friend makes threatening comments to his girlfriend at a party. What can you do safely?", answer:"<strong>Interrupt or distract</strong>, check on her privately, and tell a trusted adult or get help if it escalates."},
    ],
    mistakes:["Thinking GBV only means physical violence.","Blaming victims (“what was she wearing?”).","Believing it's “private family business” that others shouldn't report."],
    callout:{title:"Help lines", body:"GBV Command Centre: 0800 428 428 (24 hours). SMS *120*7867# for a call-back. SAPS: 10111. Childline: 116."},
    activity:"Create a list of three local places or contacts where someone experiencing GBV could get help in your area.",
    activityAnswer:"Examples: nearest police station; nearest clinic or Thuthuzela Care Centre; the GBV Command Centre number; a school counsellor or social worker.",
    examTip:"Discuss causes, effects (on victims, families, society) and solutions (personal, community, government) — a strong essay covers all three.",
    keyterms:[{w:"GBV",d:"Violence directed at someone because of their gender"},{w:"Protection order",d:"A court order that stops an abuser"},{w:"Upstander",d:"A bystander who safely takes action"}],
    quiz:[
      {q:"Controlling someone's money is:",opts:["Physical abuse","Economic abuse","Not abuse","Digital abuse"],a:1,et:"Abuse isn't only physical."},
      {q:"A protection order is obtained at a:",opts:["Clinic","Magistrate's court","School","Bank"],a:1,et:"Under the Domestic Violence Act."},
      {q:"The GBV Command Centre number is:",opts:["0800 428 428","10111","116","911"],a:0,et:"Available 24 hours."},
    ],
    conclusion:"GBV thrives on silence. Know the signs, know the help, and choose to be an upstander."},
});

// ─── Module 1: Democracy & Human Rights ─────────────────────────────────────
_loAdd('m1', {
  0: {emoji:"📜", subtitle:"Grade 10–12 · The supreme law of the land",
    illusText:"No one — not even the President — is above the Constitution.",
    hook:{title:"When the President lost in court", body:"In 2016, the Constitutional Court ruled that President Jacob Zuma had failed to uphold the Constitution by not following the Public Protector's remedial action on upgrades to his Nkandla home. He had to pay back part of the money. The case showed that in South Africa, <strong>the Constitution is supreme</strong> — it applies to everyone, including the most powerful."},
    intro:"South Africa's <strong>Constitution (1996)</strong> is the <strong>supreme law</strong>: any law or action that conflicts with it is invalid. <strong>Chapter 2</strong> is the <strong>Bill of Rights</strong>, which protects the rights of everyone in the country, including equality, dignity, life, freedom and security, privacy, freedom of expression, education, housing, health care and a healthy environment. Rights come with <strong>responsibilities</strong> and can be <strong>limited</strong> under <strong>section 36</strong> when the limitation is reasonable and justifiable in an open, democratic society. The <strong>Constitutional Court</strong> is the highest court on constitutional matters.",
    concepts:[
      {t:"green", title:"⚖️ Supremacy", body:"Parliament can't pass laws that conflict with the Constitution — courts can strike them down."},
      {t:"teal", title:"🧾 Rights and responsibilities", body:"Freedom of expression doesn't include hate speech or incitement to violence; your rights end where others' rights begin."},
      {t:"gold", title:"🏛️ Chapter 9 institutions", body:"The Public Protector, Human Rights Commission, Commission for Gender Equality, Auditor-General and Electoral Commission support democracy."},
    ],
    examples:[
      {title:"Supremacy", body:"A municipal by-law bans people of one religion from a park. Is it valid?", answer:"<strong>No</strong> — it violates the right to equality and freedom of religion, so it's unconstitutional."},
      {title:"Limitation", body:"Why can freedom of expression be limited?", answer:"To protect others' rights — e.g. <strong>hate speech</strong> and incitement to violence aren't protected."},
      {title:"Responsibility", body:"Name a responsibility that goes with the right to education.", answer:"<strong>Attending school, doing your work and respecting others' right to learn.</strong>"},
    ],
    mistakes:["Thinking rights are unlimited.","Confusing the Freedom Charter (1955) with the Constitution (1996).","Forgetting responsibilities when discussing rights."],
    callout:{title:"Read it", body:"The Constitution is short enough to read and is available free in all 11 written official languages online."},
    activity:"Choose three rights in the Bill of Rights. For each, write one matching responsibility.",
    activityAnswer:"Example: right to a healthy environment → don't litter; right to dignity → don't insult or bully; right to privacy → don't share others' messages or images.",
    examTip:"Quote the right and section number where possible (e.g. section 9: Equality) and explain how it applies to the scenario.",
    keyterms:[{w:"Constitution",d:"The supreme law of South Africa (1996)"},{w:"Bill of Rights",d:"Chapter 2 of the Constitution"},{w:"Limitation clause",d:"Section 36 — allows reasonable limits on rights"}],
    quiz:[
      {q:"The Bill of Rights is in which chapter of the Constitution?",opts:["Chapter 1","Chapter 2","Chapter 9","Chapter 14"],a:1,et:"Chapter 2."},
      {q:"Rights may be limited under section:",opts:["9","10","36","224"],a:2,et:"The limitation clause."},
      {q:"A law that conflicts with the Constitution is:",opts:["Still valid","Invalid","Valid in some provinces","Valid for 5 years"],a:1,et:"The Constitution is supreme."},
    ],
    conclusion:"The Constitution protects everyone and binds everyone. Know your rights — and your responsibilities."},

  1: {emoji:"🏠", subtitle:"Grade 10–12 · Dignity, equality, housing and health",
    illusText:"Irene Grootboom's court case changed how government must plan housing for people in crisis.",
    hook:{title:"The Grootboom case", body:"In 1998, Irene Grootboom and hundreds of others were evicted from land near Cape Town and left without shelter. In 2000, the Constitutional Court ruled that the government's housing programme was unreasonable because it made no provision for people in desperate need. The case showed that rights like housing aren't just words — courts can hold government to them."},
    intro:"Key rights include: <strong>human dignity</strong> (section 10), <strong>equality</strong> (section 9 — no unfair discrimination on grounds like race, gender, disability, religion, sexual orientation), <strong>housing</strong> (section 26), <strong>health care, food, water and social security</strong> (section 27) and <strong>education</strong> (section 29). Some socio-economic rights must be <strong>progressively realised</strong>: government must take reasonable steps, within available resources, to achieve them over time. Basic education, however, is an immediate right.",
    concepts:[
      {t:"green", title:"🧍 Dignity", body:"Everyone's inherent worth must be respected and protected — the foundation of all other rights."},
      {t:"teal", title:"📈 Progressive realisation", body:"Government must have reasonable plans and use available resources to improve access over time."},
      {t:"gold", title:"🚨 Emergency care", body:"Nobody may be refused emergency medical treatment (section 27(3))."},
    ],
    examples:[
      {title:"Which right?", body:"A hospital refuses emergency treatment to someone who can't pay.", answer:"The <strong>right to health care</strong> — section 27(3) says no one may be refused emergency treatment."},
      {title:"Progressive realisation", body:"What does it mean for housing?", answer:"Government must <strong>steadily improve access</strong> with reasonable plans, within its resources — not instantly house everyone."},
      {title:"Equality", body:"A school refuses a learner because of her religion.", answer:"Unfair discrimination — a violation of the <strong>right to equality</strong> (and education)."},
    ],
    mistakes:["Thinking the right to housing means a free house for everyone immediately.","Forgetting that dignity underpins other rights.","Not linking a scenario to a specific right."],
    callout:{title:"Where to complain", body:"The South African Human Rights Commission (SAHRC) investigates human-rights violations — complaints are free."},
    activity:"Find a news story about a community protesting about water, housing or clinics. Which constitutional right is involved, and what would “reasonable steps” look like?",
    activityAnswer:"Answers vary. A strong answer names the section (e.g. 27 for water), describes the problem and proposes reasonable steps (e.g. a repair plan, temporary water tankers, a timeline).",
    examTip:"Use the term “progressive realisation” correctly and mention a court case (e.g. Grootboom, TAC) as evidence.",
    keyterms:[{w:"Human dignity",d:"Everyone's inherent worth (section 10)"},{w:"Progressive realisation",d:"Achieving rights over time within available resources"},{w:"Socio-economic rights",d:"Rights to housing, health, food, water, education and social security"}],
    quiz:[
      {q:"The right to housing is in section:",opts:["9","10","26","29"],a:2,et:"Section 26."},
      {q:"No one may be refused emergency medical treatment under section:",opts:["27(3)","9(1)","36","12"],a:0,et:"Section 27(3)."},
      {q:"The Grootboom case was about:",opts:["Education","Housing","Elections","Taxes"],a:1,et:"Decided in 2000."},
    ],
    conclusion:"Rights to dignity, equality, housing and health are enforceable — and they guide what government must do."},

  2: {emoji:"🚫", subtitle:"Grade 10–11 · Recognising and challenging unfair treatment",
    illusText:"Discrimination can be loud — or hidden in a rule that seems neutral.",
    hook:{title:"The “neutral” rule", body:"A school rule says learners may not wear any head covering. It seems to treat everyone the same — but it affects Muslim girls who wear a hijab and Rastafarian learners far more. That's <strong>indirect discrimination</strong>: a rule that looks neutral but has an unfair effect on one group. Discrimination isn't always obvious name-calling."},
    intro:"<strong>Discrimination</strong> is treating people unfairly because of a characteristic such as race, gender, sex, pregnancy, marital status, ethnic or social origin, colour, sexual orientation, age, disability, religion, culture, language or birth (section 9). Forms include <strong>racism</strong>, <strong>sexism</strong>, <strong>homophobia</strong>, <strong>xenophobia</strong>, <strong>ableism</strong> and <strong>ageism</strong>. <strong>Direct</strong> discrimination treats someone worse openly; <strong>indirect</strong> discrimination comes from rules that seem neutral but disadvantage a group. The <strong>Promotion of Equality and Prevention of Unfair Discrimination Act (PEPUDA, 2000)</strong> gives effect to the right to equality.",
    concepts:[
      {t:"green", title:"🔎 Direct vs indirect", body:"Direct: “No foreigners may apply.” Indirect: “Applicants must have a South African matric certificate” for a job where foreign equivalents would do."},
      {t:"teal", title:"⚖️ Fair vs unfair", body:"Not all different treatment is unfair: measures to advance disadvantaged groups (e.g. employment equity) are allowed."},
      {t:"gold", title:"🗣️ Respond", body:"Speak up, support the person, report to a teacher, the SAHRC or the Equality Court."},
    ],
    examples:[
      {title:"Name it", body:"A learner in a wheelchair can't attend class because there's no ramp.", answer:"Discrimination on the ground of <strong>disability</strong> (ableism), possibly indirect."},
      {title:"Direct or indirect?", body:"A landlord says, “I don't rent to people from that country.”", answer:"<strong>Direct</strong> discrimination (xenophobia)."},
      {title:"Fair?", body:"A bursary only for learners from rural, poor schools.", answer:"Likely <strong>fair</strong> — it aims to advance disadvantaged people."},
    ],
    mistakes:["Thinking all different treatment is discrimination.","Ignoring indirect discrimination.","Describing discrimination without naming the ground (race, gender, etc.)."],
    callout:{title:"Words matter", body:"Jokes and slurs about someone's race, gender or sexuality normalise discrimination. Calling it out — calmly — changes culture."},
    activity:"Identify one rule or practice at school or in your community that might indirectly discriminate. Suggest a fairer alternative.",
    activityAnswer:"Example: a rule that only short hair is allowed for boys may disadvantage some cultures and religions; alternative: neat hair of any length, tied back if long.",
    examTip:"Define discrimination, name the ground and type (direct/indirect), and suggest a constructive response.",
    keyterms:[{w:"Discrimination",d:"Unfair treatment based on a characteristic"},{w:"Indirect discrimination",d:"A neutral-seeming rule that disadvantages a group"},{w:"PEPUDA",d:"The Equality Act of 2000"}],
    quiz:[
      {q:"Discrimination against people from other countries is:",opts:["Sexism","Xenophobia","Ageism","Ableism"],a:1,et:"Xenophobia."},
      {q:"A neutral rule that disadvantages a group is:",opts:["Direct discrimination","Indirect discrimination","Fair treatment","Affirmation"],a:1,et:"Effect matters, not just intent."},
      {q:"Which Act gives effect to the right to equality?",opts:["PEPUDA","Companies Act","BCEA","SASSA Act"],a:0,et:"Promotion of Equality and Prevention of Unfair Discrimination Act."},
    ],
    conclusion:"Discrimination can be open or hidden. Name it, understand it and challenge it — fairly."},

  3: {emoji:"🌍", subtitle:"Grade 11–12 · Two hidden dangers",
    illusText:"A job offer that's too good to be true can be a trafficking trap.",
    hook:{title:"The dream job ad", body:"A Facebook ad offers young women “modelling and hospitality jobs in Johannesburg — R25 000 a month, transport and accommodation paid”. A girl from a small town goes. When she arrives, her phone and ID are taken and she's told she owes money for the trip. This is how many <strong>human trafficking</strong> cases start. Like <strong>xenophobia</strong>, it targets vulnerable people — and spotting the signs saves lives."},
    intro:"<strong>Xenophobia</strong> is fear or hatred of foreigners. In South Africa, xenophobic violence in <strong>2008</strong> killed about 62 people, and attacks have happened since. Causes include unemployment, competition for jobs and services, and blaming foreigners for crime. <strong>Human trafficking</strong> is recruiting, moving or holding people through force, deception or coercion to exploit them — for sex, labour, begging or organ removal. South Africa's <strong>Prevention and Combating of Trafficking in Persons Act (2013)</strong> makes it a serious crime. Warning signs: unrealistic job offers, someone else holding your ID, debts you can't repay, being unable to leave.",
    concepts:[
      {t:"green", title:"🧩 Causes of xenophobia", body:"Unemployment, poverty, poor service delivery, political scapegoating and misinformation."},
      {t:"teal", title:"🎣 Trafficking tricks", body:"Fake jobs, “boyfriend” grooming, offers of study abroad, recruitment through social media."},
      {t:"gold", title:"🛡️ Stay safe", body:"Verify job offers, never hand over your ID, tell family exactly where you're going, keep emergency numbers."},
    ],
    examples:[
      {title:"Red flag", body:"An employer says they'll keep your passport “for safekeeping”.", answer:"A major <strong>trafficking red flag</strong> — never give up your ID documents."},
      {title:"Cause", body:"Give one cause of xenophobic violence.", answer:"<strong>High unemployment</strong> leading people to blame foreigners for lack of jobs."},
      {title:"Report", body:"Where can trafficking be reported?", answer:"The <strong>SAPS (10111)</strong> or the National Human Trafficking Hotline (0800 222 777)."},
    ],
    mistakes:["Assuming trafficking only happens across borders — it happens inside South Africa too.","Blaming victims of trafficking.","Repeating rumours about foreigners without evidence."],
    callout:{title:"Ubuntu", body:"Many South Africans were welcomed in other African countries during apartheid. Ubuntu means treating others with the dignity we'd want."},
    activity:"Design a social media post warning young people about fake job offers. Include three warning signs.",
    activityAnswer:"Example: “Too good to be true? 🚩 1. Huge salary for no experience. 2. They'll ‘keep your ID’. 3. You must pay a fee or ‘owe’ them for transport. Verify first — tell someone where you're going.”",
    examTip:"Distinguish causes, impacts and solutions, and include personal safety strategies and where to report.",
    keyterms:[{w:"Xenophobia",d:"Fear or hatred of foreigners"},{w:"Human trafficking",d:"Recruiting or holding people by force or deception to exploit them"},{w:"Exploitation",d:"Using someone unfairly for profit"}],
    quiz:[
      {q:"Which is a trafficking warning sign?",opts:["A signed contract you keep a copy of","An employer keeping your ID","A job interview at an office","A payslip"],a:1,et:"Never hand over your documents."},
      {q:"Major xenophobic violence occurred in South Africa in:",opts:["1994","2008","2015 only","Never"],a:1,et:"About 62 people were killed in 2008."},
      {q:"Human trafficking can happen:",opts:["Only across borders","Within South Africa too","Only to adults","Only at sea"],a:1,et:"Domestic trafficking is common."},
    ],
    conclusion:"Fear of foreigners and fake promises both prey on vulnerability. Knowledge and ubuntu are protection."},

  4: {emoji:"⚖️", subtitle:"Grade 11–12 · Justice for unfair discrimination",
    illusText:"You can bring a case to the Equality Court without a lawyer — and it's free.",
    hook:{title:"A court you can walk into", body:"When a restaurant refused to serve a group because of their race, or when someone posts hate speech online, the victims don't need expensive lawyers. They can go to the <strong>Equality Court</strong> — a special court at magistrates' courts designed to be accessible to ordinary people. It's one of the practical tools that make the right to equality real."},
    intro:"<strong>Equality Courts</strong> were set up under the <strong>Promotion of Equality and Prevention of Unfair Discrimination Act (PEPUDA, 2000)</strong>. Every magistrate's court is designated as an Equality Court. They hear cases of <strong>unfair discrimination</strong>, <strong>hate speech</strong> and <strong>harassment</strong>. Bringing a case is <strong>free</strong>, and you <strong>don't need a lawyer</strong>; a clerk helps you complete the forms. The court can order an apology, damages, changes to policies or other remedies. The <strong>SAHRC</strong> can also help complainants.",
    concepts:[
      {t:"green", title:"🚪 Access", body:"Free, informal and designed for people without lawyers. A court clerk helps."},
      {t:"teal", title:"📝 Process", body:"Complete Form 2 with the clerk → the respondent is notified → a directions hearing → the inquiry → an order."},
      {t:"gold", title:"🧾 Remedies", body:"Unconditional apology, damages, training or policy change, or an order to stop the behaviour."},
    ],
    examples:[
      {title:"Which court?", body:"A guest house refuses a same-sex couple.", answer:"The <strong>Equality Court</strong> — unfair discrimination on the ground of sexual orientation."},
      {title:"Cost", body:"How much does it cost to lay a complaint?", answer:"<strong>Nothing</strong> — it's free, and a lawyer isn't required."},
      {title:"Remedy", body:"Give one order the court can make.", answer:"An <strong>apology</strong>, <strong>damages</strong> or an order to change a discriminatory policy."},
    ],
    mistakes:["Thinking you need a lawyer.","Confusing the Equality Court with the Constitutional Court.","Not mentioning PEPUDA as the law behind it."],
    callout:{title:"Hate speech", body:"Hate speech based on race, gender, religion and other grounds can be taken to the Equality Court — including posts on social media."},
    activity:"Write a short scenario of unfair discrimination and outline the steps the victim would take at the Equality Court.",
    activityAnswer:"Example: a shop refuses entry to a learner with a guide dog. Steps: go to the magistrate's court → ask the Equality Court clerk for help → complete the complaint form → attend the hearing → the court may order an apology and a policy change.",
    examTip:"Name the Act (PEPUDA), state that it's free and accessible, and give the remedies available.",
    keyterms:[{w:"Equality Court",d:"Court that hears unfair discrimination and hate-speech cases"},{w:"Hate speech",d:"Words that incite harm or hatred against a group"},{w:"Remedy",d:"An order to fix a wrong"}],
    quiz:[
      {q:"Equality Courts are found at:",opts:["The Constitutional Court only","Magistrates' courts","Police stations","Schools"],a:1,et:"Every magistrate's court is designated."},
      {q:"Bringing a complaint to the Equality Court costs:",opts:["R5 000","Nothing","R500","Lawyer's fees"],a:1,et:"It's free."},
      {q:"Equality Courts were created under:",opts:["PEPUDA","The BCEA","The Companies Act","The SASSA Act"],a:0,et:"The 2000 Equality Act."},
    ],
    conclusion:"The Equality Court puts the right to equality within everyone's reach — no lawyer, no fee."},

  5: {emoji:"🗳️", subtitle:"Grade 10–12 · Making democracy work beyond voting",
    illusText:"Register to vote at 16, vote at 18 — and be a citizen every day in between.",
    hook:{title:"Learners who fixed their school", body:"Learners at a township school noticed broken toilets for months. Instead of giving up, their Representative Council of Learners wrote to the district, collected signatures and invited a local reporter. Within weeks, repairs started. That's <strong>active citizenship</strong> — using your rights and voice to improve your community, not just complaining."},
    intro:"<strong>Active citizenship</strong> means participating in democracy and community life. Ways to participate: <strong>registering to vote</strong> (from 16) and <strong>voting</strong> (from 18) in national, provincial and local elections run by the <strong>IEC</strong>; joining a <strong>Representative Council of Learners (RCL)</strong>; attending <strong>ward committee</strong> or community meetings; writing petitions and letters; peaceful protest; volunteering; and reporting corruption (e.g. to the Public Protector). Responsible citizens get informed, respect others' rights and hold leaders accountable.",
    concepts:[
      {t:"green", title:"🗳️ Vote", body:"Elections happen every five years nationally and provincially, and every five years locally (at a different time)."},
      {t:"teal", title:"🏘️ Local power", body:"Ward councillors and ward committees decide on many local services — water, roads, refuse. Attend meetings."},
      {t:"gold", title:"✊ Peaceful protest", body:"The right to assemble and protest is protected — peacefully and unarmed (section 17)."},
    ],
    examples:[
      {title:"Age", body:"At what age can you register to vote?", answer:"<strong>16</strong> — you can vote from <strong>18</strong>."},
      {title:"Local issue", body:"Your street has no working streetlights. Who do you contact first?", answer:"Your <strong>ward councillor</strong> (municipality)."},
      {title:"Right to protest", body:"Which conditions does section 17 set for protest?", answer:"<strong>Peacefully and unarmed</strong>."},
    ],
    mistakes:["Thinking citizenship only means voting.","Believing young people can't make a difference.","Confusing peaceful protest with violent or destructive protest."],
    callout:{title:"Register", body:"Check your registration status online at the IEC website or by SMS. It takes minutes."},
    activity:"Identify one problem at your school or in your community. Write a three-step action plan to address it as an active citizen.",
    activityAnswer:"Example: problem — litter near school. 1. RCL organises a clean-up and asks for bins. 2. Write to the ward councillor with photos. 3. Start a recycling competition between classes.",
    examTip:"Give specific, realistic actions and link them to rights (e.g. section 17, section 19 political rights).",
    keyterms:[{w:"Active citizenship",d:"Participating in community and democratic life"},{w:"IEC",d:"Electoral Commission that runs elections"},{w:"Ward councillor",d:"An elected local representative"}],
    quiz:[
      {q:"You can register to vote at age:",opts:["14","16","18","21"],a:1,et:"And vote from 18."},
      {q:"Elections in South Africa are run by the:",opts:["SAPS","IEC","SARB","SABC"],a:1,et:"The Independent Electoral Commission."},
      {q:"Section 17 protects the right to protest:",opts:["With weapons","Peacefully and unarmed","Only with permission from the President","Never"],a:1,et:"Peacefully and unarmed."},
    ],
    conclusion:"Democracy is a team sport. Vote, speak up, show up — every day, not just on election day."},
});

// ─── Module 2: Careers & Career Choices ─────────────────────────────────────
_loAdd('m2', {
  0: {subtitle:"Grade 11–12 · Planning your path beyond school",
    concepts:[
      {t:"green", title:"📋 NSC Requirements", body:"To pass matric you need 40% in your Home Language, 40% in two other subjects and 30% in three more (you may fail one subject). <strong>Higher Certificate pass</strong>: that minimum. <strong>Diploma pass</strong>: 40% in Home Language, 40% in four other high-credit subjects (Life Orientation doesn't count) and 30% in two more. <strong>Bachelor's pass</strong>: 40% in Home Language, <strong>50% in four high-credit subjects</strong> and 30% in two more, plus at least 30% in the language of learning and teaching. Universities set their own extra requirements — check each course."},
      {t:"teal", title:"💼 Career Fields", body:"<strong>STEM</strong>: requires Mathematics and Physical Sciences — engineering, medicine, data science. <strong>Business</strong>: Accounting, Business Studies, Economics — finance, management, entrepreneurship. Many careers in health, education, law, the arts and trades have their own subject and mark requirements."},
      {t:"gold", title:"💰 Funding Your Studies", body:"<strong>NSFAS</strong>: covers fees, accommodation and allowances for qualifying students at public universities and TVET colleges (combined household income of up to R350 000 a year). <strong>SETAs</strong>: sector-specific learnerships and bursaries. Company and government bursaries (e.g. Funza Lushaka for teaching) often come with a work-back agreement."},
    ],
    hook:{title:"The 2% that changed everything", body:"Ayanda got 48% for Mathematics. She needed 50% in four high-credit subjects for a Bachelor's pass — and Maths was her fourth. Two percent meant the difference between applying to university and applying for a diploma. Knowing the requirements in Grade 10 or 11 lets you plan, not panic, in Grade 12."},
    examples:[
      {title:"Which pass?", body:"Home Language 55%, four other subjects 62%, 58%, 51%, 50%, two others 35% and 40%.", answer:"A <strong>Bachelor's pass</strong> — 40%+ in Home Language, 50%+ in four subjects and 30%+ in the other two."},
      {title:"Life Orientation", body:"Can Life Orientation be one of the four 50% subjects for a Bachelor's pass?", answer:"<strong>No</strong> — LO isn't a high-credit (designated) subject for this purpose."},
      {title:"NSFAS", body:"Who qualifies for NSFAS?", answer:"South African students at public universities or TVET colleges with a <strong>combined household income of up to R350 000 a year</strong> (higher limit for students with disabilities)."},
    ],
    mistakes:["Assuming a Bachelor's pass automatically gets you into any university course.","Forgetting that Life Orientation doesn't count towards the 50% subjects.","Missing bursary deadlines, which are often months before the school year ends."],
    activityAnswer:"Answers vary. A complete answer gives the bursary name, closing date, required subjects and marks, what it covers (fees, books, accommodation) and any work-back obligation (e.g. one year of work for each year funded).",
    quiz:[
      {q:"A Bachelor's pass requires at least 50% in how many high-credit subjects?",opts:["2","3","4","6"],a:2,et:"Plus 40% in Home Language and 30% in two more."},
      {q:"For a Bachelor's pass, your Home Language must be at least:",opts:["30%","40%","50%","60%"],a:1,et:"40% in the Home Language."},
      {q:"NSFAS supports students with a combined household income of up to:",opts:["R100 000","R350 000","R1 million","Any income"],a:1,et:"Check the current NSFAS criteria each year."},
    ],
    conclusion:"Know the pass levels, the course requirements and the funding deadlines early — then plan backwards from your goal."},

  1: {emoji:"🧭", subtitle:"Grade 9–11 · Choosing subjects that keep doors open",
    illusText:"Maths Literacy closes the door to engineering. Know before you choose.",
    hook:{title:"The subject choice that closed a door", body:"In Grade 9, Sizwe chose Maths Literacy because Mathematics felt hard. In Grade 12 he discovered he wanted to study engineering — which requires Mathematics and Physical Sciences. Subject choices in Grade 9 can open or close career paths years later. Choose with your future in mind, not just this year's marks."},
    intro:"Your <strong>subject choices</strong> for Grades 10–12 affect which courses you can study. Many degrees require <strong>Mathematics</strong> (not Maths Literacy): engineering, medicine, actuarial science, accounting (CA), computer science. Health sciences usually need <strong>Physical Sciences</strong> and/or <strong>Life Sciences</strong>. Universities use an <strong>Admission Point Score (APS)</strong>: each subject's mark is converted to points — 80–100% = 7, 70–79% = 6, 60–69% = 5, 50–59% = 4, 40–49% = 3, 30–39% = 2, 0–29% = 1 — and added up (usually excluding LO).",
    concepts:[
      {t:"green", title:"🔑 Gateway subjects", body:"Mathematics and Physical Sciences keep the most doors open, especially for STEM careers."},
      {t:"teal", title:"🧮 APS", body:"Add the points for your best six subjects (excluding LO at most universities). Each course has a minimum APS."},
      {t:"gold", title:"🔍 Match interests and strengths", body:"Choose subjects you can succeed in that also lead somewhere you want to go."},
    ],
    examples:[
      {title:"Calculate APS", body:"Marks: 72%, 65%, 81%, 58%, 49%, 66%.", answer:"6 + 5 + 7 + 4 + 3 + 5 = <strong>30 points</strong>."},
      {title:"Requirement", body:"Which subject is needed for medicine but not Maths Literacy?", answer:"<strong>Mathematics</strong> (plus Physical and Life Sciences)."},
      {title:"Career path", body:"A learner loves design and drawing. Which subjects could help?", answer:"<strong>Visual Arts, EGD or Design</strong> — for architecture also Mathematics."},
    ],
    formula:"APS = sum of points for your best six subjects (80–100% = 7 … 0–29% = 1)",
    mistakes:["Choosing subjects only because friends chose them.","Assuming you can switch to Mathematics in Grade 12 without problems.","Not checking university requirements before choosing."],
    callout:{title:"Check early", body:"Every university publishes a prospectus with APS and subject requirements — read them in Grade 9 or 10."},
    activity:"Pick two careers you're interested in. Find the required subjects and minimum APS for each at one university.",
    activityAnswer:"Answers vary. A complete answer lists the course, the university, required subjects with minimum marks, and the minimum APS.",
    examTip:"When asked about subject choices, link subjects to specific careers and requirements — avoid vague answers.",
    keyterms:[{w:"APS",d:"Admission Point Score used by universities"},{w:"Prospectus",d:"A university's guide to courses and requirements"},{w:"Gateway subject",d:"A subject required for many careers"}],
    quiz:[
      {q:"A mark of 72% earns how many APS points?",opts:["5","6","7","8"],a:1,et:"70–79% = 6 points."},
      {q:"Engineering degrees usually require:",opts:["Maths Literacy","Mathematics and Physical Sciences","History","Tourism"],a:1,et:"Mathematics is essential."},
      {q:"Most universities calculate APS:",opts:["Including LO at full value","Excluding LO or counting it less","Using only one subject","Using Grade 9 marks"],a:1,et:"Check each university's rules."},
    ],
    conclusion:"Your subjects are keys. Choose the ones that unlock the doors you might want to walk through."},

  2: {emoji:"🤖", subtitle:"Grade 10–12 · Jobs that didn't exist ten years ago",
    illusText:"AI engineer, solar technician, drone pilot, cybersecurity analyst — careers of the next decade.",
    hook:{title:"Jobs your parents never heard of", body:"Ten years ago, almost nobody earned a living as a TikTok content strategist, a drone pilot or a prompt engineer. South Africa's push into solar and wind power is creating jobs for solar installers and wind-turbine technicians. Many of the jobs you'll do haven't been invented yet — so the skills you build matter as much as the job titles you know."},
    intro:"<strong>Emerging careers</strong> grow from new technology and needs: <strong>artificial intelligence and data science</strong> (analysing data, building models), <strong>cybersecurity</strong> (protecting systems and data), <strong>green energy</strong> (solar PV installers, wind technicians, energy auditors), <strong>software and app development</strong>, <strong>digital marketing and content creation</strong>, <strong>drone operation</strong>, and <strong>health technology</strong>. Employers want <strong>future skills</strong>: problem-solving, critical thinking, digital literacy, creativity, communication, teamwork and the ability to keep learning.",
    concepts:[
      {t:"green", title:"☀️ Green economy", body:"Renewable energy, recycling and water management create technical jobs — many through TVET colleges and learnerships."},
      {t:"teal", title:"💻 Digital careers", body:"Coding, data, cybersecurity and design can be learned through degrees, short courses and online platforms."},
      {t:"gold", title:"🧠 Human skills", body:"AI can't easily replace empathy, leadership, creativity and complex problem-solving."},
    ],
    examples:[
      {title:"Match the skill", body:"Which career fits someone who loves puzzles and computers and wants to stop hackers?", answer:"<strong>Cybersecurity analyst</strong>."},
      {title:"TVET route", body:"Name a green-energy career you can reach through a TVET college.", answer:"<strong>Solar PV installer</strong> or electrician specialising in renewables."},
      {title:"Future skill", body:"Why is the ability to keep learning important?", answer:"Because <strong>technology changes fast</strong> — many jobs will change several times during your career."},
    ],
    mistakes:["Thinking only degrees lead to good careers — many tech and green jobs come through TVET and short courses.","Chasing trends without checking real demand.","Ignoring human skills."],
    callout:{title:"Free learning", body:"Many free online courses (coding, data, digital marketing) offer certificates — a way to start building skills while still at school."},
    activity:"Choose one emerging career. Find out what it involves, which subjects and qualifications help, and one place in South Africa to study it.",
    activityAnswer:"Answers vary. Example: data analyst — works with data to answer business questions; helpful subjects Mathematics and CAT/IT; study a BSc or BCom in data science, or a short course.",
    examTip:"Connect careers to skills and qualifications, and mention both university and TVET routes.",
    keyterms:[{w:"Emerging career",d:"A career created by new technology or needs"},{w:"Green economy",d:"Economic activity that reduces environmental harm"},{w:"Digital literacy",d:"Using technology effectively and safely"}],
    quiz:[
      {q:"Which is an emerging green career?",opts:["Solar PV installer","Typist","Telegraph operator","Lamplighter"],a:0,et:"Renewable energy is growing in SA."},
      {q:"A skill AI finds hard to replace is:",opts:["Data entry","Empathy","Copying text","Simple sums"],a:1,et:"Human skills stay valuable."},
      {q:"Cybersecurity analysts mainly:",opts:["Design clothes","Protect systems from attacks","Repair cars","Teach PE"],a:1,et:"They defend data and networks."},
    ],
    conclusion:"Future careers reward people who build skills and keep learning. Start exploring now."},

  3: {emoji:"🎓", subtitle:"Grade 11–12 · Paying for your studies",
    illusText:"Money shouldn't stop you studying — but missing a deadline can.",
    hook:{title:"The application that came too late", body:"Thandeka got a Bachelor's pass with distinctions, but missed the NSFAS application deadline because she thought you applied after results. She had to wait a year. Funding for tertiary study exists for many students — but you must apply early, with the right documents."},
    intro:"<strong>NSFAS</strong> (National Student Financial Aid Scheme) funds South African students at public universities and TVET colleges whose combined household income is up to R350 000 a year (higher for students with disabilities); SASSA grant recipients qualify automatically on income. It covers tuition, registration, accommodation, transport, learning materials and a living allowance. Applications open online, usually towards the end of the year, <strong>before</strong> matric results. Other options: <strong>bursaries</strong> (from companies, government departments — e.g. <strong>Funza Lushaka</strong> for teaching — and SETAs), <strong>scholarships</strong> (based on merit) and <strong>study loans</strong> (must be repaid). Many bursaries include a <strong>work-back</strong> agreement.",
    concepts:[
      {t:"green", title:"📅 Timing", body:"Apply in Grade 12, before results. Deadlines are strict."},
      {t:"teal", title:"📂 Documents", body:"ID, parents' or guardians' IDs, proof of income or SASSA status, and a valid email address and cellphone number."},
      {t:"gold", title:"📝 Read the contract", body:"Bursary or loan? Work-back years? Minimum marks to keep the funding?"},
    ],
    examples:[
      {title:"Bursary or loan?", body:"Which must be repaid?", answer:"A <strong>loan</strong> must be repaid; a bursary usually doesn't (but may require work-back)."},
      {title:"Work-back", body:"A bursary funds 3 years with a 1-for-1 work-back. How long must you work for the sponsor?", answer:"<strong>3 years</strong>."},
      {title:"Teaching", body:"Which bursary funds future teachers?", answer:"<strong>Funza Lushaka</strong>."},
    ],
    mistakes:["Waiting for results before applying.","Using a cellphone number or email you'll lose access to.","Not reading the conditions of a bursary."],
    callout:{title:"Beware of scams", body:"Real NSFAS and bursary applications never require you to pay a fee to apply. Use official websites only."},
    activity:"Make a funding checklist: three possible funders for your chosen course, their deadlines and the documents you need.",
    activityAnswer:"Answers vary. A strong checklist includes NSFAS plus two bursaries relevant to the career, with closing dates and a document list.",
    examTip:"Compare funding options by cost, conditions and eligibility, and recommend one for a given scenario.",
    keyterms:[{w:"NSFAS",d:"Government funding for tertiary students"},{w:"Bursary",d:"Funding that usually doesn't have to be repaid"},{w:"Work-back",d:"Working for the sponsor after graduating"}],
    quiz:[
      {q:"When should you apply for NSFAS?",opts:["After graduating","In Grade 12, before results","Only in first year","Never"],a:1,et:"Applications open before results."},
      {q:"Which funding must be repaid?",opts:["Bursary","Scholarship","Loan","Grant"],a:2,et:"Loans are repaid with interest."},
      {q:"Funza Lushaka funds students studying to become:",opts:["Doctors","Teachers","Engineers","Pilots"],a:1,et:"A government teaching bursary."},
    ],
    conclusion:"Funding is available — but it rewards people who prepare early and read the fine print."},

  4: {emoji:"🛠️", subtitle:"Grade 11–12 · Learning while earning",
    illusText:"A learnership: classroom learning plus real workplace experience — and a stipend.",
    hook:{title:"From matric to a monthly stipend", body:"After matric, Kabelo joined a 12-month electrical learnership. Three days a week he trained at a TVET college; two days he worked with a qualified electrician — and earned a monthly stipend. He finished with a recognised qualification and work experience. Not every path starts at university."},
    intro:"<strong>SETAs</strong> (Sector Education and Training Authorities) manage skills development in different economic sectors — there are 21, e.g. the MERSETA (manufacturing, engineering), the BANKSETA and the Health and Welfare SETA. They fund <strong>learnerships</strong>, <strong>apprenticeships</strong>, <strong>internships</strong> and bursaries. A <strong>learnership</strong> combines structured learning with workplace experience and leads to a registered <strong>NQF qualification</strong>; learners usually receive a <strong>stipend</strong>. <strong>Apprenticeships</strong> lead to a trade qualification (e.g. electrician, plumber, diesel mechanic) after a trade test. Programmes like the <strong>Youth Employment Service (YES)</strong> offer young people first work experience.",
    concepts:[
      {t:"green", title:"🏭 SETAs", body:"Each SETA covers a sector and funds training linked to that sector's skills needs."},
      {t:"teal", title:"🔧 Learnerships vs apprenticeships", body:"Learnerships cover many fields; apprenticeships lead to artisan trades through a trade test."},
      {t:"gold", title:"💸 Stipend", body:"A monthly allowance to cover costs while you learn — not a full salary."},
    ],
    examples:[
      {title:"Which route?", body:"Someone wants to become a qualified plumber.", answer:"An <strong>apprenticeship</strong> ending in a trade test."},
      {title:"What's a learnership?", body:"Define a learnership.", answer:"<strong>Structured learning plus workplace experience</strong>, leading to an NQF qualification."},
      {title:"Find one", body:"Where can you find learnership opportunities?", answer:"<strong>SETA websites</strong>, TVET colleges, company career pages and the YES programme."},
    ],
    mistakes:["Thinking learnerships are only for people who didn't pass well.","Paying “agents” to get you a learnership — legitimate ones don't charge.","Confusing a stipend with a salary."],
    callout:{title:"Artisans are needed", body:"South Africa has a shortage of skilled artisans like electricians, welders and millwrights — these careers can pay well."},
    activity:"Choose a SETA linked to a career you like. List two programmes it offers and their entry requirements.",
    activityAnswer:"Answers vary. Example: MERSETA — apprenticeships for fitters and electricians (requires matric with Mathematics and Physical Sciences or N2 equivalent).",
    examTip:"Compare university, TVET and workplace routes for the same career, with advantages of each.",
    keyterms:[{w:"SETA",d:"Sector Education and Training Authority"},{w:"Learnership",d:"Structured learning plus work experience leading to an NQF qualification"},{w:"Apprenticeship",d:"Training for a trade, ending with a trade test"}],
    quiz:[
      {q:"How many SETAs are there in South Africa?",opts:["9","12","21","50"],a:2,et:"Each covers a sector."},
      {q:"A learnership leads to:",opts:["Nothing","A registered NQF qualification","A driver's licence only","A degree automatically"],a:1,et:"Plus workplace experience."},
      {q:"An apprenticeship ends with a:",opts:["Trade test","Matric exam","Driving test","Job interview only"],a:0,et:"For artisan trades."},
    ],
    conclusion:"Learnerships and apprenticeships let you earn, learn and qualify at the same time — a strong path to work."},

  5: {emoji:"🔬", subtitle:"Grade 10–12 · Investigating a career like a detective",
    illusText:"Five minutes asking someone about their job can teach you more than an hour online.",
    hook:{title:"The shadow day", body:"Naledi wanted to be a pharmacist. She spent a Saturday shadowing a pharmacist at her local clinic and discovered it was much more about patient care and less about mixing medicines than she expected. She loved it even more. Researching a career properly — including talking to real people — prevents expensive changes of course later."},
    intro:"<strong>Career research</strong> combines finding out about yourself with finding out about the world of work. Know yourself: interests, strengths, values and personality — the <strong>Holland code (RIASEC)</strong> groups interests into Realistic, Investigative, Artistic, Social, Enterprising and Conventional. Research careers: duties, working conditions, required subjects and qualifications, where to study, cost, salary range and job demand. Methods: university and TVET websites, career guides, <strong>informational interviews</strong> (asking people about their jobs), <strong>job shadowing</strong> and volunteering.",
    concepts:[
      {t:"green", title:"🧩 Know yourself", body:"Interest tests (RIASEC), feedback from others and reflecting on what activities energise you."},
      {t:"teal", title:"🗂️ Know the career", body:"Duties, qualifications, demand, salary, work environment and growth."},
      {t:"gold", title:"👀 Get real exposure", body:"Informational interviews, job shadowing and volunteering show the real day-to-day."},
    ],
    examples:[
      {title:"RIASEC", body:"Someone who loves helping and teaching people is likely which type?", answer:"<strong>Social</strong>."},
      {title:"Interview questions", body:"Give two good questions for an informational interview.", answer:"“<strong>What does a typical day look like?</strong>” and “<strong>What do you wish you'd known before starting?</strong>”"},
      {title:"Fit", body:"A learner loves building and fixing things outdoors. Which type?", answer:"<strong>Realistic</strong> — e.g. engineering technician, electrician, farmer."},
    ],
    mistakes:["Choosing a career only for salary or status.","Relying only on what friends or family say.","Not checking whether there's demand for the career."],
    callout:{title:"Ask someone", body:"Most people enjoy talking about their work. A polite WhatsApp or email asking for 10 minutes often gets a yes."},
    activity:"Conduct a 10-minute informational interview with someone working in a career you're curious about. Write down five things you learned.",
    activityAnswer:"Answers vary. A strong report includes daily tasks, qualifications needed, the best and worst parts of the job, advice for learners and whether it changed your view.",
    examTip:"Career research questions reward a structured answer: self-knowledge → career information → real-world exposure → decision.",
    keyterms:[{w:"RIASEC",d:"Holland's six interest types"},{w:"Job shadowing",d:"Spending time with someone at work to observe the job"},{w:"Informational interview",d:"A short conversation to learn about someone's career"}],
    quiz:[
      {q:"In RIASEC, someone who loves art and creativity is:",opts:["Realistic","Artistic","Conventional","Enterprising"],a:1,et:"Artistic."},
      {q:"Spending a day observing someone at work is:",opts:["Job shadowing","An internship","A learnership","A bursary"],a:0,et:"A great way to see reality."},
      {q:"Which is the best reason to choose a career?",opts:["Only the salary","A fit with your interests, strengths and values","What your friends choose","Status"],a:1,et:"Fit leads to motivation and success."},
    ],
    conclusion:"Research your career like a detective: know yourself, gather evidence and see the job for real."},
});

// ─── Module 3: Study Skills ─────────────────────────────────────────────────
_loAdd('m3', {
  0: {emoji:"🧠", subtitle:"Grade 10–12 · Remember more by testing yourself",
    illusText:"Reading your notes five times feels productive. Testing yourself once works better.",
    hook:{title:"Why highlighting doesn't work", body:"Most learners study by re-reading notes and highlighting. It feels productive — but research shows it's one of the weakest methods. The two strategies that consistently work best are <strong>active recall</strong> (testing yourself) and <strong>spaced repetition</strong> (reviewing over days, not cramming). Same time, much better results."},
    intro:"<strong>Active recall</strong> means pulling information out of your memory instead of putting it in again: close the book and write or say what you remember, answer past-paper questions, or use flashcards. <strong>Spaced repetition</strong> means reviewing material at increasing intervals (e.g. after 1 day, 3 days, a week, two weeks) to beat the <strong>forgetting curve</strong> — the way memory fades quickly after learning, first described by Hermann Ebbinghaus. The <strong>Leitner system</strong> uses flashcard boxes: cards you get right move to a box you review less often.",
    concepts:[
      {t:"green", title:"❓ Test yourself", body:"Flashcards, blank-page recall, past papers and explaining to someone else."},
      {t:"teal", title:"📅 Space it out", body:"Short sessions over many days beat one long night of cramming."},
      {t:"gold", title:"🗂️ Leitner boxes", body:"Box 1 daily, box 2 every 3 days, box 3 weekly. Right answers move up; wrong answers go back to box 1."},
    ],
    examples:[
      {title:"Active or passive?", body:"Re-reading your Life Sciences notes.", answer:"<strong>Passive</strong> — try closing the book and writing what you remember instead."},
      {title:"Plan the spacing", body:"You learn a topic on Monday. When should you review?", answer:"Tuesday, Thursday, next Monday, then two weeks later — <strong>increasing gaps</strong>."},
      {title:"Leitner", body:"You get a card wrong in box 3. Where does it go?", answer:"Back to <strong>box 1</strong>."},
    ],
    mistakes:["Cramming the night before.","Confusing familiarity (“this looks familiar”) with knowing.","Only reviewing what you already know well."],
    callout:{title:"Free tools", body:"Paper flashcards work brilliantly. Apps like Anki and Quizlet automate spaced repetition."},
    activity:"Make 10 flashcards for a topic you're studying. Test yourself today, in two days and in a week. Record your score each time.",
    activityAnswer:"Scores usually rise with each review. Cards you keep getting wrong show exactly what to focus on.",
    examTip:"Use past papers as active recall — then mark them with the memo and redo the questions you got wrong a few days later.",
    keyterms:[{w:"Active recall",d:"Retrieving information from memory to strengthen it"},{w:"Spaced repetition",d:"Reviewing at increasing intervals"},{w:"Forgetting curve",d:"How memory fades over time without review"}],
    quiz:[
      {q:"Which is active recall?",opts:["Highlighting","Re-reading","Testing yourself with flashcards","Copying notes neatly"],a:2,et:"Retrieving information builds memory."},
      {q:"Spaced repetition means:",opts:["Studying everything in one night","Reviewing over increasing intervals","Never reviewing","Studying with music"],a:1,et:"It beats the forgetting curve."},
      {q:"The forgetting curve was first described by:",opts:["Ebbinghaus","Einstein","Mandela","Newton"],a:0,et:"Hermann Ebbinghaus."},
    ],
    conclusion:"Test yourself, space it out. It's the most powerful study upgrade you can make."},

  1: {emoji:"👩‍🏫", subtitle:"Grade 10–12 · If you can't explain it simply, you don't understand it",
    illusText:"Explain photosynthesis to a 10-year-old. Where you get stuck is what you need to study.",
    hook:{title:"Teaching your little brother", body:"Zola thought she understood electric circuits — until her little brother asked her to explain why the bulb lights up. She got stuck halfway. That moment showed her exactly what she didn't understand. The <strong>Feynman Technique</strong>, named after Nobel Prize-winning physicist Richard Feynman, turns that moment into a study method."},
    intro:"The <strong>Feynman Technique</strong> has four steps: 1. <strong>Choose a concept</strong> and write its name at the top of a page. 2. <strong>Explain it in simple words</strong>, as if teaching a child — no jargon. 3. <strong>Find the gaps</strong>: where you get stuck or use vague words, go back to your notes or textbook. 4. <strong>Simplify and use an analogy</strong> — compare the idea to something familiar. It works because explaining forces you to organise knowledge and exposes what you've only memorised.",
    concepts:[
      {t:"green", title:"🗣️ Teach to learn", body:"Explaining out loud or in writing makes gaps obvious."},
      {t:"teal", title:"🔍 Find the gaps", body:"Vague phrases like “it just happens” show where understanding is missing."},
      {t:"gold", title:"🔗 Analogies", body:"Voltage is like water pressure; current is like the flow of water; resistance is like a narrow pipe."},
    ],
    examples:[
      {title:"Spot the gap", body:"“Photosynthesis is when plants make food… somehow… with sunlight.”", answer:"The gap is <strong>how</strong>: you need the inputs (CO₂, water, light) and outputs (glucose, oxygen)."},
      {title:"Analogy", body:"Give an analogy for supply and demand.", answer:"Concert tickets: <strong>few tickets + many fans = higher prices</strong>."},
      {title:"Step order", body:"What comes after explaining simply?", answer:"<strong>Identify the gaps</strong> and go back to the source."},
    ],
    mistakes:["Using textbook jargon in your explanation (that hides gaps).","Skipping the step of going back to fill gaps.","Only doing it in your head instead of writing or speaking."],
    callout:{title:"Study buddies", body:"Take turns teaching each other a topic for 5 minutes. The listener asks “why?” as often as possible."},
    activity:"Use the Feynman Technique on one topic from any subject. Write your simple explanation, circle the gaps, then rewrite it after checking your notes.",
    activityAnswer:"Answers vary. The second version should be clearer, use simple words, include an analogy and fill the gaps you circled.",
    examTip:"Explaining concepts simply also improves exam answers — markers reward clear explanations in your own words.",
    keyterms:[{w:"Feynman Technique",d:"Learning by explaining a concept simply"},{w:"Analogy",d:"Comparing an idea to something familiar"},{w:"Knowledge gap",d:"Part of a topic you don't yet understand"}],
    quiz:[
      {q:"The Feynman Technique is named after a:",opts:["Teacher","Physicist","Footballer","Poet"],a:1,et:"Richard Feynman, a Nobel Prize-winning physicist."},
      {q:"In the technique, you explain the concept as if to:",opts:["A professor","A child","An examiner","Nobody"],a:1,et:"Simple words reveal real understanding."},
      {q:"Where you get stuck shows:",opts:["You should stop","A gap to study","You're finished","Nothing"],a:1,et:"Go back and fill it."},
    ],
    conclusion:"If you can teach it simply, you know it. Use the gaps as your study map."},

  2: {emoji:"🗺️", subtitle:"Grade 10–12 · Seeing the whole topic on one page",
    illusText:"A whole chapter on one page, with colours, branches and pictures.",
    hook:{title:"The night before the History exam", body:"Mpho had 40 pages of History notes and one evening left. Instead of re-reading, he drew one big <strong>mind map</strong>: the topic in the middle, causes, events, key people and results branching out, with colours and little drawings. In the exam, he could picture the page. Visual notes help your brain see connections."},
    intro:"A <strong>mind map</strong> puts the main topic in the centre, with <strong>branches</strong> for subtopics and smaller branches for details. Use <strong>keywords</strong> (not sentences), <strong>colours</strong>, <strong>images</strong> and <strong>arrows</strong> to show links. Other visual note methods: <strong>flow charts</strong> (processes and sequences), <strong>timelines</strong> (dates), <strong>tables</strong> (comparisons) and <strong>Cornell notes</strong> (a page split into notes, cue questions and a summary). Making the map is itself a form of active learning.",
    concepts:[
      {t:"green", title:"🌳 Branch out", body:"Centre → main branches → details. One idea per branch, in a keyword or two."},
      {t:"teal", title:"🎨 Colour and images", body:"Colours group ideas; small pictures make them memorable."},
      {t:"gold", title:"🧭 Choose the right visual", body:"Mind map for overviews, flow chart for processes, timeline for history, table for comparisons."},
    ],
    examples:[
      {title:"Which visual?", body:"Steps of mitosis.", answer:"A <strong>flow chart</strong> — it's a sequence."},
      {title:"Which visual?", body:"Comparing a sole trader with a company.", answer:"A <strong>table</strong>."},
      {title:"Keywords", body:"Turn “The Group Areas Act of 1950 divided towns into areas for different races” into a branch.", answer:"<strong>Group Areas Act · 1950 · racial zones</strong>."},
    ],
    mistakes:["Writing full sentences on branches.","Making it so decorative that it takes hours.","Never reviewing the map after making it."],
    callout:{title:"Combine methods", body:"Make a mind map, then cover it and redraw it from memory — that adds active recall."},
    activity:"Make a mind map of one chapter you're studying. Then cover it and redraw as much as you can from memory.",
    activityAnswer:"Answers vary. Compare the two maps — anything missing from the second is what to review.",
    examTip:"In the exam, a quick mind map of your essay plan helps you organise points before writing.",
    keyterms:[{w:"Mind map",d:"A diagram with a central topic and branching ideas"},{w:"Flow chart",d:"A diagram showing steps in order"},{w:"Cornell notes",d:"Notes split into notes, cues and a summary"}],
    quiz:[
      {q:"In a mind map, the main topic goes:",opts:["At the bottom","In the centre","Nowhere","In a footnote"],a:1,et:"Branches spread outwards."},
      {q:"The best visual for a sequence of steps is a:",opts:["Mind map","Flow chart","Pie chart","Poem"],a:1,et:"Flow charts show order."},
      {q:"Branches should contain:",opts:["Full paragraphs","Keywords","Nothing","Only numbers"],a:1,et:"Keywords keep it clear."},
    ],
    conclusion:"See the big picture on one page. Then cover it and recall it."},

  3: {emoji:"🗓️", subtitle:"Grade 10–12 · Planning time so it doesn't plan you",
    illusText:"25 minutes of focus, 5 minutes of rest. Repeat. That's the Pomodoro Technique.",
    hook:{title:"Where did the weekend go?", body:"Friday: “I'll study all weekend.” Sunday night: three hours on TikTok, a family function, a soccer match… and one page of notes. Sound familiar? A realistic <strong>study timetable</strong> isn't about studying all the time — it's about knowing exactly what you'll study, when, so the time actually gets used."},
    intro:"A good <strong>study timetable</strong> starts with fixed commitments (school, chores, sport, church), then schedules <strong>specific</strong> study tasks (“Maths: Ex 4.3 questions 1–10”, not just “Maths”). Prioritise subjects by difficulty and exam dates; mix subjects to keep focus. Use the <strong>Pomodoro Technique</strong>: 25 minutes of focused work, 5-minute break, and a longer break after four rounds. Put your phone in another room or on airplane mode. Review the timetable each week and adjust.",
    concepts:[
      {t:"green", title:"🎯 Be specific", body:"Each slot names the subject AND the task — vague plans are easy to skip."},
      {t:"teal", title:"🍅 Pomodoro", body:"25 min focus + 5 min break × 4, then a 15–30 min break."},
      {t:"gold", title:"📵 Remove distractions", body:"Phone out of reach, notifications off, a regular study spot."},
    ],
    examples:[
      {title:"Count the Pomodoros", body:"How many 25-minute Pomodoros (with 5-minute breaks) fit in 2 hours?", answer:"Each cycle is 30 minutes → <strong>4 Pomodoros</strong>."},
      {title:"Make it specific", body:"Improve: “Saturday: study Science.”", answer:"“Saturday 9:00–10:00: <strong>Physical Sciences — Newton's laws, 10 past-paper questions</strong>.”"},
      {title:"Prioritise", body:"Maths exam in 3 days, History in 10. What gets more time this week?", answer:"<strong>Maths</strong> — sooner and usually needs more practice."},
    ],
    mistakes:["Planning 8 hours of study on a weekend day — it won't happen.","Not scheduling breaks or rest.","Never adjusting a plan that isn't working."],
    callout:{title:"Rest counts", body:"Sleep, exercise and time with friends aren't wasted — they help your brain consolidate what you learned."},
    activity:"Create a one-week study timetable with at least five specific study tasks and four Pomodoro sessions per day on weekdays (around your commitments).",
    activityAnswer:"Answers vary. A strong timetable shows fixed commitments, specific tasks per subject, breaks, a rest day or evening and a weekly review slot.",
    examTip:"Start exam revision at least six weeks early, and plan backwards from each exam date.",
    keyterms:[{w:"Pomodoro Technique",d:"25 minutes of focus followed by a short break"},{w:"Prioritise",d:"Decide what's most important or urgent"},{w:"Procrastination",d:"Delaying tasks you should do"}],
    quiz:[
      {q:"A Pomodoro is usually:",opts:["5 minutes","25 minutes","60 minutes","3 hours"],a:1,et:"Followed by a 5-minute break."},
      {q:"Which plan is most effective?",opts:["Study Maths","Maths: Ex 4.3, Q1–10","Do some work","Study everything"],a:1,et:"Specific tasks get done."},
      {q:"After four Pomodoros you should:",opts:["Stop studying forever","Take a longer break","Skip the break","Go to bed"],a:1,et:"15–30 minutes."},
    ],
    conclusion:"Plan specific tasks, work in focused bursts, rest well, and adjust each week."},

  4: {emoji:"📝", subtitle:"Grade 10–12 · Working smart in the exam room",
    illusText:"Past papers are the closest thing to seeing the exam before you write it.",
    hook:{title:"The learner who saw the paper coming", body:"Every matric exam has questions that look a lot like questions from previous years. Learners who practise past papers under timed conditions recognise question types, know how marks are allocated and finish on time. The Department of Basic Education publishes past papers and memos free online — one of the best study resources there is."},
    intro:"<strong>Exam strategy</strong> starts before the exam: practise <strong>past papers</strong> under timed conditions and mark them with the <strong>memorandum</strong>. In the exam: read the instructions, spend the first few minutes reading the whole paper, allocate time by marks (e.g. 150 minutes ÷ 150 marks = 1 minute per mark), start with questions you know well to build confidence, show all working, and leave time to check. Never leave a question blank — partial answers can earn marks.",
    concepts:[
      {t:"green", title:"📚 Past papers", body:"Do them timed, mark them honestly with the memo, and redo the questions you got wrong."},
      {t:"teal", title:"⏱️ Time by marks", body:"Divide the time by the total marks. Don't spend 20 minutes on a 4-mark question."},
      {t:"gold", title:"✍️ Show working", body:"Method marks can be earned even if the final answer is wrong."},
    ],
    examples:[
      {title:"Time per mark", body:"A 3-hour paper is worth 150 marks.", answer:"180 ÷ 150 = <strong>1.2 minutes per mark</strong>."},
      {title:"A 20-mark question", body:"Using 1.2 minutes per mark, how long should it take?", answer:"20 × 1.2 = <strong>24 minutes</strong>."},
      {title:"Blank or guess?", body:"You're unsure of a multiple-choice question.", answer:"<strong>Eliminate wrong options and choose</strong> — a blank earns nothing."},
    ],
    mistakes:["Not reading instructions (e.g. “answer any TWO”).","Spending too long on one question.","Not checking answers at the end."],
    callout:{title:"Where to find papers", body:"Past NSC papers and memos are free on the Department of Basic Education's website — download a few per subject."},
    activity:"Do one past paper section under timed conditions. Mark it with the memo and list the three question types you lost the most marks on.",
    activityAnswer:"Answers vary. The list shows exactly what to practise next — use active recall and redo similar questions.",
    examTip:"Write the time you should finish each question in the margin at the start of the exam.",
    keyterms:[{w:"Memorandum (memo)",d:"The marking guideline for an exam"},{w:"Mark allocation",d:"How many marks a question is worth"},{w:"Method marks",d:"Marks for correct working"}],
    quiz:[
      {q:"A 2-hour paper is worth 100 marks. Time per mark:",opts:["0.5 min","1.2 min","2 min","1 min"],a:1,et:"120 ÷ 100 = 1.2."},
      {q:"Past papers are best done:",opts:["Untimed, with the memo open","Timed, then marked with the memo","Never","Only the night before"],a:1,et:"Simulate the real exam."},
      {q:"If unsure in a multiple-choice question, you should:",opts:["Leave it blank","Eliminate options and choose","Choose A always","Skip the paper"],a:1,et:"Blanks earn nothing."},
    ],
    conclusion:"Practise like it's the exam, then write the exam like it's practice — calm, timed and strategic."},

  5: {emoji:"🌿", subtitle:"Grade 10–12 · Keeping calm when it counts",
    illusText:"Breathe in 4, hold 4, out 4, hold 4. Your nervous system listens.",
    hook:{title:"The blank mind", body:"Lindiwe knew her work, but when she opened the exam paper her heart raced and her mind went blank. That's the stress response — useful for running from danger, not for writing an exam. Exam stress is normal, but there are proven ways to manage it so it helps you focus instead of freezing you."},
    intro:"<strong>Stress</strong> is the body's response to pressure. A little can sharpen focus; too much causes anxiety, poor sleep, headaches and blanking. Manage it with: <strong>preparation</strong> (a study plan reduces uncertainty); <strong>sleep</strong> (teenagers need about 8–10 hours); <strong>exercise</strong>; <strong>healthy food and water</strong>; <strong>breathing techniques</strong> such as <strong>box breathing</strong> (in 4, hold 4, out 4, hold 4); <strong>positive self-talk</strong>; and <strong>talking to someone</strong>. Avoid all-nighters, energy drinks and comparing yourself to others. If stress becomes overwhelming, get help — e.g. the SADAG helpline.",
    concepts:[
      {t:"green", title:"😴 Sleep", body:"Sleep stores memories. An all-nighter before an exam usually lowers your score."},
      {t:"teal", title:"🫁 Breathing", body:"Slow breathing calms the nervous system in under a minute — use it before and during the exam."},
      {t:"gold", title:"🗣️ Talk", body:"Teachers, parents, friends, counsellors — and helplines if it feels too much."},
    ],
    examples:[
      {title:"Box breathing", body:"Describe box breathing.", answer:"Breathe <strong>in 4 seconds, hold 4, out 4, hold 4</strong>, and repeat."},
      {title:"Healthy or not?", body:"Staying up all night with energy drinks before the exam.", answer:"<strong>Unhealthy</strong> — it worsens memory and anxiety."},
      {title:"Self-talk", body:"Replace “I'm going to fail.”", answer:"“<strong>I've prepared. I'll do my best, one question at a time.</strong>”"},
    ],
    mistakes:["Thinking stress means you're weak.","Cramming all night.","Keeping overwhelming feelings to yourself."],
    callout:{title:"Help is available", body:"SADAG (South African Depression and Anxiety Group): 0800 567 567 (24 hours). Childline: 116."},
    activity:"Write your personal exam-week plan: sleep time, study blocks, exercise, meals and one calming technique.",
    activityAnswer:"Answers vary. A strong plan includes 8+ hours of sleep, specific study blocks, daily movement, regular meals and a breathing or relaxation technique.",
    examTip:"If you blank in the exam, stop, breathe slowly for a minute, move to a question you know, and come back later.",
    keyterms:[{w:"Stress",d:"The body's response to pressure"},{w:"Box breathing",d:"Breathing in a 4-4-4-4 pattern to calm down"},{w:"Self-talk",d:"The way you speak to yourself in your mind"}],
    quiz:[
      {q:"Teenagers need about how much sleep?",opts:["4–5 hours","6 hours","8–10 hours","12–14 hours"],a:2,et:"Sleep consolidates memory."},
      {q:"Box breathing uses a pattern of:",opts:["1-1-1-1","4-4-4-4","10-0-10-0","Holding your breath as long as possible"],a:1,et:"In, hold, out, hold."},
      {q:"SADAG's 24-hour helpline is:",opts:["0800 567 567","10111","116","112"],a:0,et:"For anxiety, depression and crisis support."},
    ],
    conclusion:"Stress is normal — and manageable. Prepare, sleep, breathe and reach out."},
});

// ─── Module 4: Physical Education ───────────────────────────────────────────
_loAdd('m4', {
  0: {emoji:"🏃", subtitle:"Grade 10–12 · What “fit” really means",
    illusText:"A marathon runner and a weightlifter are both fit — in different ways.",
    hook:{title:"Who's the fittest?", body:"Who's fitter: a Comrades runner, a Springbok prop or a ballet dancer? Each is fit — for different things. The runner has amazing endurance, the prop has strength and power, and the dancer has flexibility and balance. <strong>Physical fitness</strong> has several components, and a balanced programme trains all of them."},
    intro:"<strong>Health-related fitness</strong> components: <strong>cardiovascular endurance</strong> (heart and lungs supplying oxygen over time), <strong>muscular strength</strong> (maximum force), <strong>muscular endurance</strong> (repeating movements without tiring), <strong>flexibility</strong> (range of movement at joints) and <strong>body composition</strong> (proportion of fat to lean mass). <strong>Skill-related fitness</strong> components: <strong>agility</strong>, <strong>balance</strong>, <strong>coordination</strong>, <strong>power</strong>, <strong>reaction time</strong> and <strong>speed</strong>.",
    concepts:[
      {t:"green", title:"❤️ Health-related", body:"Cardiovascular endurance, strength, muscular endurance, flexibility, body composition."},
      {t:"teal", title:"⚡ Skill-related", body:"Agility, balance, coordination, power, reaction time, speed — important for sport."},
      {t:"gold", title:"🧪 Fitness tests", body:"Beep test (cardio), push-ups (muscular endurance), sit-and-reach (flexibility), standing long jump (power)."},
    ],
    examples:[
      {title:"Name the component", body:"A goalkeeper diving to stop a penalty.", answer:"<strong>Reaction time</strong> (and power, agility)."},
      {title:"Which test?", body:"How would you test flexibility?", answer:"The <strong>sit-and-reach</strong> test."},
      {title:"Which component?", body:"Doing as many push-ups as possible in one minute.", answer:"<strong>Muscular endurance</strong>."},
    ],
    mistakes:["Confusing muscular strength (one maximum effort) with muscular endurance (many repetitions).","Thinking fitness only means being thin.","Training only one component."],
    callout:{title:"Free fitness", body:"Many towns have free weekly parkruns (5 km), open-air gyms and community sports clubs."},
    activity:"Do three fitness tests (e.g. push-ups in 1 minute, sit-and-reach, a timed 1 km). Record your results and retest in four weeks.",
    activityAnswer:"Answers vary. Improvement after four weeks shows the effect of regular training.",
    examTip:"Give a sport example for each component — it shows you understand, not just memorised.",
    keyterms:[{w:"Cardiovascular endurance",d:"The heart and lungs' ability to supply oxygen over time"},{w:"Agility",d:"Changing direction quickly"},{w:"Flexibility",d:"Range of movement at a joint"}],
    quiz:[
      {q:"The sit-and-reach test measures:",opts:["Speed","Flexibility","Power","Strength"],a:1,et:"Range of movement."},
      {q:"Which is skill-related fitness?",opts:["Body composition","Agility","Flexibility","Muscular endurance"],a:1,et:"Agility, balance, coordination, power, reaction time, speed."},
      {q:"Running a long distance mainly uses:",opts:["Cardiovascular endurance","Power","Reaction time","Balance"],a:0,et:"Heart and lungs working over time."},
    ],
    conclusion:"Fitness has many parts. Train them all for health — and the ones your sport needs most."},

  1: {emoji:"💪", subtitle:"Grade 10–12 · Why moving matters for body and mind",
    illusText:"60 minutes of activity a day — for your heart, your bones and your mood.",
    hook:{title:"The mood booster you already own", body:"After a 30-minute walk or a game of soccer, most people feel calmer and happier. That's not imagination: exercise releases <strong>endorphins</strong> and helps the brain manage stress. The World Health Organization recommends that young people get <strong>at least 60 minutes</strong> of moderate-to-vigorous physical activity every day."},
    intro:"Regular exercise has <strong>physical benefits</strong>: a stronger heart and lungs, healthier weight, stronger bones and muscles, better sleep and lower risk of diseases like type 2 diabetes, high blood pressure and heart disease. <strong>Mental benefits</strong>: less stress, anxiety and depression, better concentration and memory, more confidence. <strong>Social benefits</strong>: teamwork, friendships and belonging. Young people should aim for 60 minutes a day of moderate-to-vigorous activity, including muscle- and bone-strengthening activities at least three times a week.",
    concepts:[
      {t:"green", title:"❤️ Physical", body:"Heart, lungs, bones, muscles, weight and sleep all improve."},
      {t:"teal", title:"🧠 Mental", body:"Endorphins lift mood; exercise improves focus and memory — good for exam season."},
      {t:"gold", title:"🤝 Social", body:"Team sports, dance and parkrun build friendships and teamwork."},
    ],
    examples:[
      {title:"Moderate or vigorous?", body:"Brisk walking to school.", answer:"<strong>Moderate</strong> — you can talk but not sing."},
      {title:"Mental benefit", body:"Give one mental benefit of exercise.", answer:"<strong>Reduced stress and anxiety</strong> (or better concentration)."},
      {title:"Disease prevention", body:"Name a lifestyle disease regular exercise helps prevent.", answer:"<strong>Type 2 diabetes</strong> (or high blood pressure, heart disease)."},
    ],
    mistakes:["Thinking exercise must be in a gym.","Exercising hard once a week instead of moving regularly.","Ignoring mental and social benefits."],
    callout:{title:"Fit it in", body:"Walk or cycle to school, take the stairs, dance at home, play street soccer — it all counts."},
    activity:"Track your physical activity for a week. Did you reach 60 minutes a day? Plan two ways to add activity.",
    activityAnswer:"Answers vary. Many learners fall short on weekdays. Ideas: walk part of the way to school, join a team, a 20-minute workout before supper.",
    examTip:"Organise benefits into physical, mental and social, with one example each.",
    keyterms:[{w:"Endorphins",d:"Brain chemicals that improve mood"},{w:"Moderate activity",d:"Raises heart rate; you can talk but not sing"},{w:"Lifestyle disease",d:"A disease linked to habits such as diet and inactivity"}],
    quiz:[
      {q:"The WHO recommends young people get how much activity daily?",opts:["10 minutes","30 minutes","60 minutes","3 hours"],a:2,et:"Moderate-to-vigorous."},
      {q:"Exercise releases mood-boosting chemicals called:",opts:["Endorphins","Enzymes","Hormones only","Proteins"],a:0,et:"They improve mood."},
      {q:"Which is a social benefit of exercise?",opts:["Stronger bones","Teamwork and friendships","Lower blood pressure","Better sleep"],a:1,et:"Physical, mental and social benefits."},
    ],
    conclusion:"Move every day — your body, mind and friendships all benefit."},

  2: {emoji:"🧘", subtitle:"Grade 10–12 · Preparing the body and preventing injury",
    illusText:"Five minutes of warm-up can save five weeks of injury.",
    hook:{title:"The hamstring that tore", body:"Thabo arrived late for soccer, skipped the warm-up and sprinted onto the field. Ten minutes later he pulled his hamstring and was out for a month. Cold muscles are stiff and more likely to tear. A proper <strong>warm-up</strong> and <strong>cool-down</strong> is one of the simplest ways to stay in the game."},
    intro:"A <strong>warm-up</strong> (about 10 minutes) gradually raises heart rate and body temperature and prepares muscles and joints: <strong>light cardio</strong> (jogging), <strong>dynamic stretches</strong> (leg swings, arm circles, lunges) and <strong>sport-specific drills</strong>. A <strong>cool-down</strong> (5–10 minutes) gradually lowers heart rate: light jogging or walking, then <strong>static stretches</strong> (holding each stretch about 15–30 seconds). Other safety measures: correct equipment and technique, hydration, checking the playing area and not playing through pain.",
    concepts:[
      {t:"green", title:"🔥 Warm-up", body:"Pulse raiser → dynamic stretches → sport-specific movements."},
      {t:"teal", title:"❄️ Cool-down", body:"Easy movement → static stretches held 15–30 seconds."},
      {t:"gold", title:"🦺 Safe practice", body:"Proper equipment, water, safe surfaces, correct technique and rest."},
    ],
    examples:[
      {title:"Dynamic or static?", body:"Leg swings before a match.", answer:"<strong>Dynamic</strong> — moving stretches suit warm-ups."},
      {title:"Order", body:"Put in order: static stretches, light jog, sport drills, dynamic stretches.", answer:"Warm-up: <strong>light jog → dynamic stretches → sport drills</strong>; static stretches belong in the cool-down."},
      {title:"Why cool down?", body:"Give one reason to cool down.", answer:"It <strong>gradually lowers heart rate</strong> and can reduce stiffness."},
    ],
    mistakes:["Doing long static stretches on cold muscles before sprinting.","Skipping the cool-down.","Playing through sharp pain."],
    callout:{title:"Hydrate", body:"Drink water before, during and after exercise, especially in hot South African summers."},
    activity:"Design a 10-minute warm-up and 5-minute cool-down for your favourite sport.",
    activityAnswer:"Example for soccer: warm-up — 3 min jog, 3 min dynamic stretches (leg swings, high knees), 4 min passing and short sprints. Cool-down — 2 min walk, 3 min static stretches (hamstrings, quads, calves).",
    examTip:"Name the three phases of a warm-up and explain the purpose of each.",
    keyterms:[{w:"Dynamic stretch",d:"A stretch done while moving"},{w:"Static stretch",d:"A stretch held still for a time"},{w:"Warm-up",d:"Preparing the body for exercise"}],
    quiz:[
      {q:"Static stretches are best done:",opts:["Before sprinting","In the cool-down","Never","During the match"],a:1,et:"Hold 15–30 seconds."},
      {q:"The first part of a warm-up is usually:",opts:["Static stretching","A light pulse raiser like jogging","Sprinting","Resting"],a:1,et:"Raise heart rate gradually."},
      {q:"A cool-down helps to:",opts:["Raise heart rate","Lower heart rate gradually","Start a game","Build speed"],a:1,et:"Bring the body back to rest."},
    ],
    conclusion:"Warm up to perform, cool down to recover — two habits that keep you in the game."},

  3: {emoji:"🧊", subtitle:"Grade 10–12 · First aid for sprains and strains",
    illusText:"Rest. Ice. Compression. Elevation. Four steps for the first 48 hours.",
    hook:{title:"The rolled ankle", body:"During a netball match, Palesa lands awkwardly and rolls her ankle. It swells fast. What her teammates do in the next few minutes can make the difference between a short recovery and weeks of pain. For minor soft-tissue injuries like sprains and strains, remember <strong>RICE</strong>."},
    intro:"<strong>RICE</strong> is first aid for minor sprains (ligament injuries) and strains (muscle injuries) in the first 24–48 hours: <strong>Rest</strong> — stop playing and avoid putting weight on the injury. <strong>Ice</strong> — apply ice wrapped in a cloth for about 15–20 minutes every few hours (never directly on the skin). <strong>Compression</strong> — wrap firmly (not tightly) with a bandage to reduce swelling. <strong>Elevation</strong> — raise the injured part above heart level. Get medical help for severe pain, a deformed joint, inability to bear weight, numbness, or suspected head injury.",
    concepts:[
      {t:"green", title:"🛑 Rest and ice", body:"Stop activity; ice in a cloth for 15–20 minutes to reduce pain and swelling."},
      {t:"teal", title:"🩹 Compression and elevation", body:"Firm bandage and raised limb reduce swelling."},
      {t:"gold", title:"🚑 When to get help", body:"Suspected fracture, dislocation, head injury, severe pain or numbness — call for medical help (ambulance 10177)."},
    ],
    examples:[
      {title:"Apply RICE", body:"A player twists an ankle. First action?", answer:"<strong>Stop playing and rest</strong> — then ice, compress and elevate."},
      {title:"Ice safely", body:"How should ice be applied?", answer:"<strong>Wrapped in a cloth for 15–20 minutes</strong>, not directly on skin."},
      {title:"Not RICE", body:"A player hits their head and is confused.", answer:"Possible <strong>concussion</strong> — remove from play and get medical help; RICE isn't enough."},
    ],
    mistakes:["Putting ice directly on the skin.","Wrapping a bandage so tight that toes go numb.","Continuing to play on an injury."],
    callout:{title:"Emergency numbers", body:"Ambulance: 10177. From a cellphone: 112. Learn basic first aid — it saves lives."},
    activity:"Role-play applying RICE to a classmate's “sprained ankle”, explaining each step aloud.",
    activityAnswer:"Steps: sit them down (rest); wrapped ice pack for 15–20 minutes (ice); firm bandage from toes up (compression); ankle raised on a bag above heart level (elevation).",
    examTip:"Write out what each letter stands for and the reason for each step.",
    keyterms:[{w:"Sprain",d:"Injury to a ligament"},{w:"Strain",d:"Injury to a muscle or tendon"},{w:"Concussion",d:"A brain injury caused by a blow to the head"}],
    quiz:[
      {q:"In RICE, the C stands for:",opts:["Cold","Compression","Care","Cast"],a:1,et:"A firm bandage."},
      {q:"Ice should be applied for about:",opts:["2 minutes","15–20 minutes","2 hours","All night"],a:1,et:"Wrapped in a cloth."},
      {q:"An injury to a ligament is a:",opts:["Strain","Sprain","Fracture","Cramp"],a:1,et:"Strains affect muscles."},
    ],
    conclusion:"RICE handles minor sprains and strains. Know when it's not enough and call for help."},

  4: {emoji:"🎯", subtitle:"Grade 10–12 · Moving for fun, community and culture",
    illusText:"Every Saturday morning, thousands of South Africans walk or run a free 5 km parkrun.",
    hook:{title:"Saturday morning at parkrun", body:"Every Saturday morning, people of all ages walk, jog or run a free, timed 5 km <strong>parkrun</strong> at hundreds of venues across South Africa. Some are chasing personal bests; many are just there for fun and company. <strong>Recreational activities</strong> are about enjoyment, health and community — not winning trophies."},
    intro:"<strong>Recreational activities</strong> are done for enjoyment and well-being in free time: walking, hiking, cycling, swimming, dancing, community sports, parkrun and outdoor adventure. <strong>Indigenous games</strong> are part of South African heritage: <strong>morabaraba</strong> (a strategy board game), <strong>diketo</strong> (a stone-throwing hand–eye game), <strong>kgati</strong> (rope skipping), <strong>dibeke</strong> (a running-and-ball game) and <strong>ncuva</strong>. Benefits: fitness, stress relief, social connection and cultural pride. Consider safety, cost and access when choosing activities.",
    concepts:[
      {t:"green", title:"🎲 Indigenous games", body:"Morabaraba, diketo, kgati and dibeke — fun, cheap and part of our heritage."},
      {t:"teal", title:"🌄 Outdoor recreation", body:"Hiking, cycling and swimming — with safety planning (route, water, buddy, weather)."},
      {t:"gold", title:"🏘️ Community", body:"Parkrun, community leagues and dance groups build belonging."},
    ],
    examples:[
      {title:"Indigenous game", body:"Which game uses stones and hand–eye coordination?", answer:"<strong>Diketo</strong>."},
      {title:"Low-cost activity", body:"Suggest a free recreational activity.", answer:"<strong>Parkrun</strong>, walking, street soccer or a home dance workout."},
      {title:"Hike safely", body:"Name two safety measures for a hike.", answer:"<strong>Tell someone your route and go with a buddy</strong>; take water, a charged phone and check the weather."},
    ],
    mistakes:["Thinking recreation must be competitive.","Ignoring safety in outdoor activities.","Forgetting indigenous games as a recreational option."],
    callout:{title:"Heritage", body:"Indigenous games tournaments are held at schools and festivals around Heritage Month (September)."},
    activity:"Teach a younger family member or friend an indigenous game. Write a short set of rules.",
    activityAnswer:"Example — diketo: players sit around a hole with stones; toss one stone up, move stones in or out of the hole with the same hand before catching it; drop it and your turn ends.",
    examTip:"Link recreational activities to health, social and cultural benefits, and mention safety.",
    keyterms:[{w:"Recreation",d:"Activities done for enjoyment in free time"},{w:"Indigenous games",d:"Traditional games from local cultures"},{w:"Morabaraba",d:"A traditional strategy board game"}],
    quiz:[
      {q:"Morabaraba is a:",opts:["Running race","Strategy board game","Swimming stroke","Dance"],a:1,et:"A traditional strategy game."},
      {q:"Parkrun distance is:",opts:["2 km","5 km","10 km","21 km"],a:1,et:"Free and timed, on Saturdays."},
      {q:"Diketo mainly develops:",opts:["Hand–eye coordination","Swimming","Strength","Endurance"],a:0,et:"Throwing and catching stones."},
    ],
    conclusion:"Recreation keeps you healthy and connected. Find something you enjoy — and share it."},

  5: {emoji:"📈", subtitle:"Grade 10–12 · Measuring progress like an athlete",
    illusText:"Maximum heart rate ≈ 220 − age. Train in the right zone.",
    hook:{title:"The smartwatch question", body:"Your friend's smartwatch shows a heart rate of 150 during a run and says she's in the “cardio zone”. What does that mean — and how can you train smart without a watch? Tracking a few simple measures shows whether your fitness is improving and keeps you motivated."},
    intro:"Simple fitness measures: <strong>resting heart rate</strong> (beats per minute when relaxed — usually 60–100; fitter people often have lower), <strong>maximum heart rate</strong> (estimated as <strong>220 − age</strong>), and <strong>target heart-rate zones</strong> (moderate exercise at about 50–70% of maximum, vigorous at about 70–85%). Take your pulse at the wrist or neck for 15 seconds and multiply by 4. Other tracking: timed runs, push-up counts, flexibility tests, step counts and a training diary. <strong>BMI</strong> (body mass index) = mass (kg) ÷ height² (m²) gives a rough guide, but doesn't distinguish muscle from fat.",
    concepts:[
      {t:"green", title:"💓 Heart rate", body:"Pulse for 15 s × 4 = beats per minute."},
      {t:"teal", title:"🎯 Target zones", body:"Max HR ≈ 220 − age; moderate 50–70%, vigorous 70–85% of max."},
      {t:"gold", title:"📒 Training diary", body:"Record the date, activity, duration, effort and how you felt — progress becomes visible."},
    ],
    examples:[
      {title:"Max heart rate", body:"Estimate the maximum heart rate of a 16-year-old.", answer:"220 − 16 = <strong>204 beats per minute</strong>."},
      {title:"Vigorous zone", body:"What's 70% of 204?", answer:"0.7 × 204 ≈ <strong>143 bpm</strong> — the start of the vigorous zone."},
      {title:"Pulse", body:"You count 18 beats in 15 seconds.", answer:"18 × 4 = <strong>72 bpm</strong>."},
    ],
    formula:"Max heart rate ≈ 220 − age · BMI = mass (kg) ÷ height² (m²)",
    mistakes:["Using BMI as the only measure of health (it doesn't separate muscle and fat).","Measuring pulse with your thumb (it has its own pulse).","Comparing your progress only with others instead of your own past results."],
    callout:{title:"No gadgets needed", body:"A watch with a second hand and a notebook are enough to track your fitness."},
    activity:"Measure your resting heart rate on three mornings and calculate your maximum and moderate-zone heart rates.",
    activityAnswer:"Answers vary. Example for a 15-year-old: max ≈ 205 bpm; moderate zone ≈ 103–144 bpm (50–70%).",
    examTip:"Show the formula and calculation for heart-rate questions, and explain what the result means for training.",
    keyterms:[{w:"Resting heart rate",d:"Heartbeats per minute at rest"},{w:"Target heart-rate zone",d:"Heart-rate range for a training intensity"},{w:"BMI",d:"Body mass index: mass ÷ height²"}],
    quiz:[
      {q:"Estimated maximum heart rate for a 17-year-old:",opts:["183","203","217","237"],a:1,et:"220 − 17 = 203."},
      {q:"20 beats in 15 seconds equals:",opts:["60 bpm","80 bpm","100 bpm","35 bpm"],a:1,et:"20 × 4 = 80."},
      {q:"A limitation of BMI is that it:",opts:["Is hard to calculate","Doesn't distinguish muscle from fat","Uses heart rate","Only works for adults over 60"],a:1,et:"Muscular athletes can have a high BMI."},
    ],
    conclusion:"Measure, record, improve. Your own progress is the best motivation."},
});

